// PARTICLES 2.0 TIER B — the GPU-COMPUTE particle tier (parity-plan Phase 1).
// The CPU pool (`world.fx`) stays the workhorse for bursts and small streams;
// THIS system is for counts the CPU can never touch: 100k+ particles fully
// simulated on the GPU. One emitter = one persistent particle pool living in
// storage buffers; a compute kernel spawns (ring-window, no atomics needed),
// integrates forces-as-data (accel / drag / CURL NOISE / attract / vortex /
// orbit), collides against the DEPTH BUFFER (sparks skitter down any
// geometry on screen — zero collider setup), and compacts the alive set into
// a drawIndirect argument buffer. The CPU never touches a particle: the GPU
// decides what exists AND how many quads to draw.
//
// Render: camera-facing quads (velocity-STRETCHED when asked) with the
// familiar option surface — ramp-over-life, twinkle, soft/glow discs or
// atlas frames — plus SOFT PARTICLES (fragment fades near scene depth: no
// hard quad intersections, ever). Additive by default: at these counts the
// pool is unsorted, and additive blending is order-independent (normal
// alpha would flicker by submission order).
//
// Depth plumbing (set up by Game/World3d, documented here because this is
// the consumer): the 3D pass is split opaque → translucent. The opaque pass
// STORES depth into a dedicated sampleable texture; the translucent pass
// (where these particles draw) binds it read-only for soft fades — that is
// THIS frame's depth. The compute kernel runs before either pass, so
// collision tests against LAST frame's depth with LAST frame's viewProj —
// one frame of latency, invisible in practice. A zeroed depth texture
// (first frame / resize) reads as "no data" via the d==0 guard.
//
// Module load is DOM/GPU-free; the maths (hash, value noise, curl, spawn,
// integration) is exported as pure CPU twins of the WGSL and dist-tested —
// the crTrail precedent: geometry/sim maths gets asserted on CPU, never
// judged from pixels.

import { BITS, shaderModule } from './gpu.js';
import { resolveRamp, type RampName } from './particles.js';
import { rgba } from './color.js';
import { DEPTH_FORMAT } from './batch.js';
import type { Mat4 } from './math3d.js';
import { mat4Inverse } from './math3d.js';
import type { Atlas } from './atlas.js';

// ---------------------------------------------------------------------------
// Forces as DATA — the MCP-block shape. 8 slots × 2 vec4s in the uniform.

export type GpuForce =
  /** Constant acceleration — gravity is { kind: 'accel', y: -9.8 }, wind is a sideways one. */
  | { kind: 'accel'; x?: number; y?: number; z?: number }
  /** Velocity damping per second (0..~5). */
  | { kind: 'drag'; amount?: number }
  /** Divergence-free curl-noise flow — smoke/magic that SWIRLS. `scale` =
   * noise features per world unit (default 0.35), `speed` = how fast the
   * flow field itself evolves (default 0.4). */
  | { kind: 'curl'; strength?: number; scale?: number; speed?: number }
  /** Pull toward (push from, with negative strength) a point. `radius` is
   * the falloff softening distance (default 3). */
  | { kind: 'attract'; x?: number; y?: number; z?: number; strength?: number; radius?: number }
  /** Swirl around an axis through a point (tornado). `ax/ay/az` = axis
   * (default +Y up); tangential force peaks one unit from the axis. */
  | { kind: 'vortex'; x?: number; y?: number; z?: number; ax?: number; ay?: number; az?: number; strength?: number }
  /** Orbit a point around the +Y axis: tangential drive + a spring toward
   * the `radius` shell (accretion discs, halos). */
  | { kind: 'orbit'; x?: number; y?: number; z?: number; strength?: number; radius?: number; spring?: number };

export const MAX_GPU_FORCES = 8;
const FORCE_KIND: Record<GpuForce['kind'], number> = { accel: 1, drag: 2, curl: 3, attract: 4, vortex: 5, orbit: 6 };

/** Pack a force list into the uniform's 8×2-vec4 layout (pure, dist-tested). */
export function packForces(forces: GpuForce[]): Float32Array<ArrayBuffer> {
  const out = new Float32Array(MAX_GPU_FORCES * 8);
  forces.slice(0, MAX_GPU_FORCES).forEach((f, i) => {
    const o = i * 8;
    out[o] = FORCE_KIND[f.kind];
    switch (f.kind) {
      case 'accel':
        out[o + 1] = f.x ?? 0; out[o + 2] = f.y ?? 0; out[o + 3] = f.z ?? 0;
        break;
      case 'drag':
        out[o + 4] = f.amount ?? 1;
        break;
      case 'curl':
        out[o + 4] = f.strength ?? 4; out[o + 5] = f.scale ?? 0.35; out[o + 6] = f.speed ?? 0.4;
        break;
      case 'attract':
        out[o + 1] = f.x ?? 0; out[o + 2] = f.y ?? 0; out[o + 3] = f.z ?? 0;
        out[o + 4] = f.strength ?? 6; out[o + 5] = Math.max(0.01, f.radius ?? 3);
        break;
      case 'vortex': {
        out[o + 1] = f.x ?? 0; out[o + 2] = f.y ?? 0; out[o + 3] = f.z ?? 0;
        const l = Math.hypot(f.ax ?? 0, f.ay ?? 0, f.az ?? 0);
        out[o + 4] = f.strength ?? 6;
        if (l > 0) { out[o + 5] = (f.ax ?? 0) / l; out[o + 6] = (f.ay ?? 0) / l; out[o + 7] = (f.az ?? 0) / l; }
        else { out[o + 5] = 0; out[o + 6] = 1; out[o + 7] = 0; }
        break;
      }
      case 'orbit':
        out[o + 1] = f.x ?? 0; out[o + 2] = f.y ?? 0; out[o + 3] = f.z ?? 0;
        out[o + 4] = f.strength ?? 4; out[o + 5] = f.radius ?? 4; out[o + 6] = f.spring ?? 2;
        break;
    }
  });
  return out;
}

// ---------------------------------------------------------------------------
// The pure maths — CPU twins of the WGSL, bit-matching the integer hashing so
// tests pin the exact logic the kernel runs. All u32 arithmetic via imul/>>>.

/** PCG hash (u32 in, u32 out) — the kernel's randomness source. */
export function pcg(v: number): number {
  const state = (Math.imul(v >>> 0, 747796405) + 2891336453) >>> 0;
  const word = Math.imul((state >>> (((state >>> 28) + 4) & 31)) ^ state, 277803737) >>> 0;
  return ((word >>> 22) ^ word) >>> 0;
}

/** u32 hash → [0, 1). */
export function rand01(h: number): number {
  return (h >>> 0) / 4294967296;
}

function latticeHash(x: number, y: number, z: number, seed: number): number {
  const h = (Math.imul(x | 0, 1597334677) ^ Math.imul(y | 0, 3812015801) ^ Math.imul(z | 0, 2798796415) ^ (seed >>> 0)) >>> 0;
  return pcg(h);
}

/** 3D value noise on an integer lattice, trilinear smoothstep — [0, 1). */
export function vnoise3(x: number, y: number, z: number, seed: number): number {
  const ix = Math.floor(x), iy = Math.floor(y), iz = Math.floor(z);
  const fx = x - ix, fy = y - iy, fz = z - iz;
  const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy), uz = fz * fz * (3 - 2 * fz);
  const c = (dx: number, dy: number, dz: number) => rand01(latticeHash(ix + dx, iy + dy, iz + dz, seed));
  const x00 = c(0, 0, 0) + (c(1, 0, 0) - c(0, 0, 0)) * ux;
  const x10 = c(0, 1, 0) + (c(1, 1, 0) - c(0, 1, 0)) * ux;
  const x01 = c(0, 0, 1) + (c(1, 0, 1) - c(0, 0, 1)) * ux;
  const x11 = c(0, 1, 1) + (c(1, 1, 1) - c(0, 1, 1)) * ux;
  const y0 = x00 + (x10 - x00) * uy;
  const y1 = x01 + (x11 - x01) * uy;
  return y0 + (y1 - y0) * uz;
}

const CURL_E = 0.25;

/** Curl of a hash-noise potential field — divergence-free by construction
 * (∇·(∇×ψ) = 0), which is WHY curl flow swirls instead of clumping: the
 * dist test asserts numerical divergence ≈ 0. */
export function curl3(x: number, y: number, z: number, seed: number): [number, number, number] {
  const e = CURL_E, k = 1 / (2 * e);
  const px = (xx: number, yy: number, zz: number) => vnoise3(xx, yy, zz, seed + 11);
  const py = (xx: number, yy: number, zz: number) => vnoise3(xx, yy, zz, seed + 37);
  const pz = (xx: number, yy: number, zz: number) => vnoise3(xx, yy, zz, seed + 71);
  return [
    (pz(x, y + e, z) - pz(x, y - e, z)) * k - (py(x, y, z + e) - py(x, y, z - e)) * k,
    (px(x, y, z + e) - px(x, y, z - e)) * k - (pz(x + e, y, z) - pz(x - e, y, z)) * k,
    (py(x + e, y, z) - py(x - e, y, z)) * k - (px(x, y + e, z) - px(x, y - e, z)) * k,
  ];
}

/** CPU twin of the kernel's WRAP fold: map `v` into the extent-`e` box
 * centred on `c`, torus-style (e <= 0 = unwrapped). Runs per axis; the
 * kernel applies it AFTER the integration step. */
export function wrap1(v: number, c: number, e: number): number {
  if (e <= 0) return v;
  const rel = v - c + e / 2;
  return c + ((rel / e - Math.floor(rel / e)) * e - e / 2);
}

/** Is pool slot `i` inside this frame's spawn ring window [s0, s0+n) mod cap? */
export function inSpawnWindow(i: number, spawn0: number, n: number, capacity: number): boolean {
  if (n <= 0) return false;
  const rel = (i - spawn0 + capacity) % capacity;
  return rel < n;
}

/** The CPU-visible particle state (the kernel's 12-float record). */
export interface GpuP {
  x: number; y: number; z: number; age: number;
  vx: number; vy: number; vz: number; life: number;
  size: number; seed: number; spin: number;
}

/** Spawn-shape/motion inputs the init consumes (a subset of the emitter opts,
 * already defaulted — see GpuEmitter.resolved). */
export interface GpuSpawn {
  x: number; y: number; z: number;
  dirX: number; dirY: number; dirZ: number; spread: number;
  speed: number; speedVar: number; life: number; lifeVar: number;
  size: number; sizeVar: number; spin: number;
  spawnRadius: number; ring: number;
  boxW: number; boxH: number; boxD: number;
}

/** CPU twin of the kernel's spawn init: particle `i` under frame-seed `seed`.
 * Deterministic — same (i, seed) always births the same particle. */
export function spawnGpuParticle(i: number, seed: number, s: GpuSpawn): GpuP {
  const h0 = pcg((i >>> 0) ^ pcg(seed));
  const r = (n: number) => rand01(pcg((h0 + n) >>> 0));
  const dl = Math.hypot(s.dirX, s.dirY, s.dirZ);
  const directional = dl > 1e-6 && s.spread < Math.PI * 2 - 1e-6;
  let nx: number, ny: number, nz: number;
  if (directional) {
    const ax = s.dirX / dl, ay = s.dirY / dl, az = s.dirZ / dl;
    const ux = Math.abs(ax) < 0.9 ? 1 : 0;
    const uy = ux ? 0 : 1;
    let bx = -az * uy, by = az * ux, bz = ax * uy - ay * ux;
    const bl = Math.hypot(bx, by, bz) || 1;
    bx /= bl; by /= bl; bz /= bl;
    const cx = ay * bz - az * by, cy = az * bx - ax * bz, cz = ax * by - ay * bx;
    const cosT = 1 - r(1) * (1 - Math.cos(s.spread / 2));
    const sinT = Math.sqrt(Math.max(0, 1 - cosT * cosT));
    const phi = r(2) * Math.PI * 2;
    const pb = Math.cos(phi) * sinT, pc = Math.sin(phi) * sinT;
    nx = ax * cosT + bx * pb + cx * pc;
    ny = ay * cosT + by * pb + cy * pc;
    nz = az * cosT + bz * pb + cz * pc;
  } else {
    const zz = r(1) * 2 - 1;
    const phi = r(2) * Math.PI * 2;
    const sq = Math.sqrt(Math.max(0, 1 - zz * zz));
    nx = Math.cos(phi) * sq; ny = zz; nz = Math.sin(phi) * sq;
  }
  const v = Math.max(0, s.speed + (r(3) - 0.5) * 2 * s.speedVar);
  let x = s.x, y = s.y, z = s.z;
  if (s.ring > 0) {
    const ra = r(8) * Math.PI * 2;
    x += Math.cos(ra) * s.ring;
    z += Math.sin(ra) * s.ring;
  }
  x += (r(9) - 0.5) * s.boxW;
  y += (r(10) - 0.5) * s.boxH;
  z += (r(11) - 0.5) * s.boxD;
  if (s.spawnRadius > 0) {
    const zz = r(12) * 2 - 1;
    const phi = r(13) * Math.PI * 2;
    const sq = Math.sqrt(Math.max(0, 1 - zz * zz));
    const rr = Math.cbrt(r(14)) * s.spawnRadius;
    x += Math.cos(phi) * sq * rr;
    y += zz * rr;
    z += Math.sin(phi) * sq * rr;
  }
  // Radial (spread < 0 sentinel — the kernel's dir.w): velocity away from
  // the origin, falling back to the sphere direction at the exact origin.
  if (s.spread < 0) {
    const rx = x - s.x, ry = y - s.y, rz = z - s.z;
    const rl = Math.hypot(rx, ry, rz);
    if (rl > 1e-5) { nx = rx / rl; ny = ry / rl; nz = rz / rl; }
  }
  return {
    x, y, z, age: 0,
    vx: nx * v, vy: ny * v, vz: nz * v,
    life: Math.max(0.05, s.life + (r(4) - 0.5) * 2 * s.lifeVar),
    size: Math.max(0.001, s.size + (r(5) - 0.5) * 2 * s.sizeVar),
    spin: (r(6) - 0.5) * 2 * s.spin,
    seed: r(7),
  };
}

/** CPU twin of the kernel's integration step (no collision — that needs a
 * depth buffer). Mutates and returns `p`. `flutter`/`flutterFreq` mirror
 * the emitter options (the falling-leaf rock). */
export function stepGpuParticle(p: GpuP, forces: Float32Array | number[], forceCount: number, dt: number, time: number, flutter = 0, flutterFreq = 0.7): GpuP {
  p.age += dt;
  if (p.age >= p.life) return p;
  let ax = 0, ay = 0, az = 0, drag = 0;
  for (let fi = 0; fi < forceCount; fi++) {
    const o = fi * 8;
    const kind = forces[o] | 0;
    if (kind === 1) {
      ax += forces[o + 1]; ay += forces[o + 2]; az += forces[o + 3];
    } else if (kind === 2) {
      drag += forces[o + 4];
    } else if (kind === 3) {
      const st = forces[o + 4], sc = forces[o + 5], sp = forces[o + 6];
      const t = time * sp;
      const c = curl3(p.x * sc + t, p.y * sc + t * 0.87, p.z * sc + t * 1.13, 7);
      ax += c[0] * st; ay += c[1] * st; az += c[2] * st;
    } else if (kind === 4) {
      const dx = forces[o + 1] - p.x, dy = forces[o + 2] - p.y, dz = forces[o + 3] - p.z;
      const rr = Math.hypot(dx, dy, dz);
      const rad = forces[o + 5];
      const k = (forces[o + 4] / Math.max(1e-4, rr)) * (rad * rad) / (rad * rad + rr * rr);
      ax += dx * k; ay += dy * k; az += dz * k;
    } else if (kind === 5) {
      const rx = p.x - forces[o + 1], ry = p.y - forces[o + 2], rz = p.z - forces[o + 3];
      const axx = forces[o + 5], axy = forces[o + 6], axz = forces[o + 7];
      const d = rx * axx + ry * axy + rz * axz;
      const px = rx - axx * d, py = ry - axy * d, pz = rz - axz * d;
      const rr = Math.hypot(px, py, pz);
      // tangent = axis × radial; force peaks one unit out, plus a gentle
      // inward pull so the swirl doesn't fling everything away.
      const tx = axy * pz - axz * py, ty = axz * px - axx * pz, tz = axx * py - axy * px;
      const tl = Math.hypot(tx, ty, tz) || 1;
      const st = forces[o + 4];
      const k = (st * rr) / (1 + rr * rr);
      ax += (tx / tl) * k - (px / Math.max(1e-4, rr)) * st * 0.15;
      ay += (ty / tl) * k - (py / Math.max(1e-4, rr)) * st * 0.15;
      az += (tz / tl) * k - (pz / Math.max(1e-4, rr)) * st * 0.15;
    } else if (kind === 6) {
      const rx = p.x - forces[o + 1], rz = p.z - forces[o + 3];
      const rr = Math.hypot(rx, rz) || 1e-4;
      const st = forces[o + 4], rad = forces[o + 5], spring = forces[o + 6];
      ax += (-rz / rr) * st + (rx / rr) * (rad - rr) * spring;
      az += (rx / rr) * st + (rz / rr) * (rad - rr) * spring;
      ay += (forces[o + 2] - p.y) * spring * 0.5;
    }
  }
  if (flutter > 0) {
    const ph = p.seed * Math.PI * 2;
    const sway = Math.sin((time + p.seed * 3.7) * flutterFreq * Math.PI * 2 + ph);
    ax += Math.cos(ph) * sway * flutter;
    az += Math.sin(ph) * sway * flutter;
  }
  p.vx += ax * dt; p.vy += ay * dt; p.vz += az * dt;
  const damp = drag > 0 ? Math.max(0, 1 - drag * dt) : 1;
  p.vx *= damp; p.vy *= damp; p.vz *= damp;
  p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
  return p;
}

// ---------------------------------------------------------------------------
// WGSL — assembled as pure strings (dist-testable), one variant per depth
// texture type (the world's MSAA sampleCount is fixed at creation).

const P_FLOATS = 12;
// float offsets into the emitter uniform (kept in one place; the pack() and
// the WGSL struct below must agree — a dist test walks the struct fields):
// 13 vec4s of scalars, 16 vec4s of forces (52..115), two mat4s (116..147),
// 8 ramp vec4s (148..179) = 180 floats.
const O = {
  spawn: 0, origin: 4, dir: 8, box: 12, motion: 16, shape: 20,
  look: 24, look2: 28, uv: 32, hit: 36, softp: 40, screen: 44, flut: 48,
  wrapv: 52, forces: 56, prevVP: 120, prevInv: 136, ramp: 152,
} as const;
const EU_TOTAL = 184;

const COMMON_WGSL = /* wgsl */ `
struct EU {
  spawn: vec4f,     // spawn0, spawnN, seed, dt
  origin: vec4f,    // x, y, z, spawnRadius
  dir: vec4f,       // dir xyz (zero = omni), spread
  box: vec4f,       // box w/h/d, ring radius
  motion: vec4f,    // speed, speedVar, life, lifeVar
  shape: vec4f,     // size, sizeVar, spin, capacity
  look: vec4f,      // endSize, fade, alpha, twinkle
  look2: vec4f,     // add, soft, stretch, rampMode (0 solid / 1 life / 2 palette)
  uv: vec4f,        // atlas frame rect
  hit: vec4f,       // collideMode (0 off / 1 bounce / 2 kill), bounce, friction, thickness
  softp: vec4f,     // softFade, time, projA, projB (viewDist = projB / (projA + depth))
  screen: vec4f,    // depthW, depthH, forceCount, frameMode
  flut: vec4f,      // flutter, flutterFreq, tumble, tumbleSpeed
  wrapv: vec4f,     // wrap extents w/h/d (0 = that axis unwrapped), on flag
  forces: array<vec4f, 16>,
  prevVP: mat4x4f,
  prevInv: mat4x4f,
  ramp: array<vec4f, 8>,
}
struct P {
  pos: vec4f,       // xyz + age
  vel: vec4f,       // xyz + life (0 = never lived)
  ext: vec4f,       // size, seed, spin, restAge (0 = live; else the age it came to rest)
}
fn pcg(v: u32) -> u32 {
  let state = v * 747796405u + 2891336453u;
  let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
  return (word >> 22u) ^ word;
}
fn rand01(h: u32) -> f32 {
  return f32(h) * 2.3283064365386963e-10;
}
`;

const NOISE_WGSL = /* wgsl */ `
fn latticeHash(x: i32, y: i32, z: i32, seed: u32) -> u32 {
  let h = (bitcast<u32>(x) * 1597334677u) ^ (bitcast<u32>(y) * 3812015801u) ^ (bitcast<u32>(z) * 2798796415u) ^ seed;
  return pcg(h);
}
fn vnoise3(p: vec3f, seed: u32) -> f32 {
  let i = vec3i(floor(p));
  let f = p - floor(p);
  let u = f * f * (3.0 - 2.0 * f);
  let c000 = rand01(latticeHash(i.x, i.y, i.z, seed));
  let c100 = rand01(latticeHash(i.x + 1, i.y, i.z, seed));
  let c010 = rand01(latticeHash(i.x, i.y + 1, i.z, seed));
  let c110 = rand01(latticeHash(i.x + 1, i.y + 1, i.z, seed));
  let c001 = rand01(latticeHash(i.x, i.y, i.z + 1, seed));
  let c101 = rand01(latticeHash(i.x + 1, i.y, i.z + 1, seed));
  let c011 = rand01(latticeHash(i.x, i.y + 1, i.z + 1, seed));
  let c111 = rand01(latticeHash(i.x + 1, i.y + 1, i.z + 1, seed));
  let x00 = mix(c000, c100, u.x);
  let x10 = mix(c010, c110, u.x);
  let x01 = mix(c001, c101, u.x);
  let x11 = mix(c011, c111, u.x);
  return mix(mix(x00, x10, u.y), mix(x01, x11, u.y), u.z);
}
fn curl3(p: vec3f, seed: u32) -> vec3f {
  let e = 0.25;
  let k = 1.0 / (2.0 * e);
  let dzy = (vnoise3(p + vec3f(0.0, e, 0.0), seed + 71u) - vnoise3(p - vec3f(0.0, e, 0.0), seed + 71u)) * k;
  let dyz = (vnoise3(p + vec3f(0.0, 0.0, e), seed + 37u) - vnoise3(p - vec3f(0.0, 0.0, e), seed + 37u)) * k;
  let dxz = (vnoise3(p + vec3f(0.0, 0.0, e), seed + 11u) - vnoise3(p - vec3f(0.0, 0.0, e), seed + 11u)) * k;
  let dzx = (vnoise3(p + vec3f(e, 0.0, 0.0), seed + 71u) - vnoise3(p - vec3f(e, 0.0, 0.0), seed + 71u)) * k;
  let dyx = (vnoise3(p + vec3f(e, 0.0, 0.0), seed + 37u) - vnoise3(p - vec3f(e, 0.0, 0.0), seed + 37u)) * k;
  let dxy = (vnoise3(p + vec3f(0.0, e, 0.0), seed + 11u) - vnoise3(p - vec3f(0.0, e, 0.0), seed + 11u)) * k;
  return vec3f(dzy - dyz, dxz - dzx, dyx - dxy);
}
`;

/** Assemble the compute kernel (pure string work — dist-tested). `ms` picks
 * the depth binding type to match the world's MSAA mode. */
export function buildGpuParticleComputeWGSL(ms: boolean): string {
  const depthDecl = ms
    ? 'var depthTex: texture_depth_multisampled_2d;'
    : 'var depthTex: texture_depth_2d;';
  return /* wgsl */ `
${COMMON_WGSL}
${NOISE_WGSL}
struct DrawArgs {
  vertexCount: u32,
  instanceCount: atomic<u32>,
  firstVertex: u32,
  firstInstance: u32,
  live: atomic<u32>,        // true alive count (the readback stat) — in
  pad0: u32,                // STABLE-ORDER mode instanceCount is the whole
  pad1: u32,                // pool, so it can't double as the count
  pad2: u32,
}
@group(0) @binding(0) var<uniform> u: EU;
@group(0) @binding(1) var<storage, read_write> parts: array<P>;
@group(0) @binding(2) var<storage, read_write> alive: array<u32>;
@group(0) @binding(3) var<storage, read_write> args: DrawArgs;
@group(0) @binding(4) ${depthDecl}

fn loadDepth(px: vec2i) -> f32 {
  return textureLoad(depthTex, px, 0);
}

fn unproject(px: vec2f, d: f32) -> vec3f {
  let ndc = vec3f(
    (px.x / u.screen.x) * 2.0 - 1.0,
    1.0 - (px.y / u.screen.y) * 2.0,
    d,
  );
  let w = u.prevInv * vec4f(ndc, 1.0);
  return w.xyz / w.w;
}

fn spawn(i: u32) -> P {
  let h0 = pcg(i ^ pcg(u32(u.spawn.z)));
  let r1 = rand01(pcg(h0 + 1u));
  let r2 = rand01(pcg(h0 + 2u));
  let r3 = rand01(pcg(h0 + 3u));
  let r4 = rand01(pcg(h0 + 4u));
  let r5 = rand01(pcg(h0 + 5u));
  let r6 = rand01(pcg(h0 + 6u));
  let r7 = rand01(pcg(h0 + 7u));
  let r8 = rand01(pcg(h0 + 8u));
  let r9 = rand01(pcg(h0 + 9u));
  let r10 = rand01(pcg(h0 + 10u));
  let r11 = rand01(pcg(h0 + 11u));
  let r12 = rand01(pcg(h0 + 12u));
  let r13 = rand01(pcg(h0 + 13u));
  let r14 = rand01(pcg(h0 + 14u));
  let dl = length(u.dir.xyz);
  var n: vec3f;
  if (dl > 1e-6 && u.dir.w < 6.2831843) {
    // Cone: uniform over the solid angle around the (normalised) axis.
    let a = u.dir.xyz / dl;
    var uax = vec3f(0.0, 1.0, 0.0);
    if (abs(a.x) < 0.9) { uax = vec3f(1.0, 0.0, 0.0); }
    let b = normalize(cross(a, uax));
    let c = cross(a, b);
    let cosT = 1.0 - r1 * (1.0 - cos(u.dir.w * 0.5));
    let sinT = sqrt(max(0.0, 1.0 - cosT * cosT));
    let phi = r2 * 6.2831853;
    n = a * cosT + b * (cos(phi) * sinT) + c * (sin(phi) * sinT);
  } else {
    // Uniform sphere direction (Marsaglia via z + angle).
    let zz = r1 * 2.0 - 1.0;
    let phi = r2 * 6.2831853;
    let sq = sqrt(max(0.0, 1.0 - zz * zz));
    n = vec3f(cos(phi) * sq, zz, sin(phi) * sq);
  }
  let v = max(0.0, u.motion.x + (r3 - 0.5) * 2.0 * u.motion.y);
  var pos = u.origin.xyz;
  if (u.box.w > 0.0) {
    let ra = r8 * 6.2831853;
    pos += vec3f(cos(ra) * u.box.w, 0.0, sin(ra) * u.box.w);
  }
  pos += (vec3f(r9, r10, r11) - 0.5) * u.box.xyz;
  if (u.origin.w > 0.0) {
    let zz = r12 * 2.0 - 1.0;
    let phi = r13 * 6.2831853;
    let sq = sqrt(max(0.0, 1.0 - zz * zz));
    let rr = pow(r14, 0.333333) * u.origin.w;
    pos += vec3f(cos(phi) * sq, zz, sin(phi) * sq) * rr;
  }
  // RADIAL emission (dir.w < 0 sentinel): velocity points AWAY from the
  // emitter origin — shockwaves/novas/explosion shells. Falls back to the
  // sphere direction when the spawn landed exactly on the origin.
  if (u.dir.w < 0.0) {
    let rd = pos - u.origin.xyz;
    let rl = length(rd);
    if (rl > 1e-5) { n = rd / rl; }
  }
  var out: P;
  out.pos = vec4f(pos, 0.0);
  out.vel = vec4f(n * v, max(0.05, u.motion.z + (r4 - 0.5) * 2.0 * u.motion.w));
  out.ext = vec4f(
    max(0.001, u.shape.x + (r5 - 0.5) * 2.0 * u.shape.y),
    r7,
    (r6 - 0.5) * 2.0 * u.shape.z,
    0.0,
  );
  return out;
}

@compute @workgroup_size(64)
fn cs(@builtin(global_invocation_id) gid: vec3u) {
  let i = gid.x;
  let cap = u32(u.shape.w);
  if (i >= cap) { return; }
  let dt = u.spawn.w;
  var p = parts[i];
  let rel = (f32(i) - u.spawn.x + u.shape.w) % u.shape.w;
  if (u.spawn.y > 0.0 && rel < u.spawn.y) {
    p = spawn(i);
  } else if (p.vel.w > 0.0 && p.pos.w < p.vel.w) {
    p.pos.w = p.pos.w + dt;
    // A RESTED particle (ext.w > 0) lies still: it ages and fades but no
    // forces, no motion, no further collision — a petal on the ground.
    if (p.pos.w < p.vel.w && p.ext.w == 0.0) {
      // Integrate forces (data-driven; twin: stepGpuParticle).
      var acc = vec3f(0.0);
      var drag = 0.0;
      let nf = u32(u.screen.z);
      for (var fi = 0u; fi < nf; fi = fi + 1u) {
        let fa = u.forces[fi * 2u];
        let fb = u.forces[fi * 2u + 1u];
        let kind = u32(fa.x);
        if (kind == 1u) {
          acc += fa.yzw;
        } else if (kind == 2u) {
          drag += fb.x;
        } else if (kind == 3u) {
          let t = u.softp.y * fb.z;
          acc += curl3(p.pos.xyz * fb.y + vec3f(t, t * 0.87, t * 1.13), 7u) * fb.x;
        } else if (kind == 4u) {
          let d = fa.yzw - p.pos.xyz;
          let rr = length(d);
          let rad = fb.y;
          let k = (fb.x / max(1e-4, rr)) * (rad * rad) / (rad * rad + rr * rr);
          acc += d * k;
        } else if (kind == 5u) {
          let rl = p.pos.xyz - fa.yzw;
          let ax = fb.yzw;
          let rad = rl - ax * dot(rl, ax);
          let rr = length(rad);
          let tang = cross(ax, rad);
          let tl = max(1e-6, length(tang));
          let k = (fb.x * rr) / (1.0 + rr * rr);
          acc += (tang / tl) * k - (rad / max(1e-4, rr)) * fb.x * 0.15;
        } else if (kind == 6u) {
          let rx = p.pos.x - fa.y;
          let rz = p.pos.z - fa.w;
          let rr = max(1e-4, length(vec2f(rx, rz)));
          acc += vec3f(
            (-rz / rr) * fb.x + (rx / rr) * (fb.y - rr) * fb.z,
            (fa.z - p.pos.y) * fb.z * 0.5,
            (rx / rr) * fb.x + (rz / rr) * (fb.y - rr) * fb.z,
          );
        }
      }
      // FLUTTER: the falling-leaf rock — a per-particle horizontal
      // oscillation (direction and phase from the seed), what makes petals
      // and leaves swing side-to-side instead of raining straight down.
      if (u.flut.x > 0.0) {
        let ph = p.ext.y * 6.2831853;
        let sway = sin((u.softp.y + p.ext.y * 3.7) * u.flut.y * 6.2831853 + ph);
        acc += vec3f(cos(ph), 0.0, sin(ph)) * (sway * u.flut.x);
      }
      var vel = p.vel.xyz + acc * dt;
      if (drag > 0.0) { vel *= max(0.0, 1.0 - drag * dt); }
      var pos = p.pos.xyz + vel * dt;
      var respawned = false;
      // DEPTH-BUFFER collision: last frame's depth under last frame's
      // matrices (one frame late — invisible). d == 0 means no data
      // (zero-initialised texture on the first frame / after resize).
      if (u.hit.x > 0.5) {
        let clip = u.prevVP * vec4f(pos, 1.0);
        if (clip.w > 0.01) {
          let ndc = clip.xyz / clip.w;
          if (abs(ndc.x) < 1.0 && abs(ndc.y) < 1.0 && ndc.z > 0.0 && ndc.z < 1.0) {
            let px = vec2i(
              i32((ndc.x * 0.5 + 0.5) * u.screen.x),
              i32((0.5 - ndc.y * 0.5) * u.screen.y),
            );
            let d = loadDepth(px);
            if (d > 0.0 && d < 1.0) {
              let sceneDist = u.softp.w / (u.softp.z + d);
              let partDist = clip.w;
              // Contact = behind the surface along the ray AND within
              // thickness of the actual surface POINT in 3D. The ray test
              // alone over-triggers at GRAZING incidence (near the horizon
              // a ray skims the ground, so a huge stretch of air sits
              // within thickness ray-units of it — Rich's "the floor rose
              // up and rain vanished below the horizon"); it survives as a
              // cheap pre-filter because |partDist - sceneDist| never
              // exceeds |pos - surface| (triangle inequality).
              let sp = unproject(vec2f(px), d);
              if (partDist > sceneDist - 0.02 && partDist - sceneDist < u.hit.w
                  && distance(pos, sp) < u.hit.w) {
                if (u.hit.x > 1.5 && u.hit.x < 2.5) {
                  p.pos.w = p.vel.w; // kill on contact
                } else if (u.hit.x > 3.5) {
                  // RESPAWN on contact: re-run the spawn init — the drop
                  // dies at the surface and is instantly reborn (infinite
                  // rain from one burst, nothing accumulates or floats).
                  p = spawn(i);
                  // FLUX-PRESERVING rebirth: re-enter at the box face
                  // OPPOSITE the emission direction (rain: the top). A
                  // uniform-volume rebirth makes each column's cycle time
                  // depend on its first-hit height — the sky's rain
                  // density then paints a ghost image of the ground's
                  // height map (Rich caught it: object shapes visible in
                  // the fresh rain). Uniform influx per face area = a
                  // uniform sky. Omni emitters keep the volume rebirth.
                  let ad = abs(u.dir.xyz);
                  if (max(ad.x, max(ad.y, ad.z)) > 1e-4) {
                    let hf = u.box.xyz * 0.5;
                    if (ad.y >= ad.x && ad.y >= ad.z) {
                      p.pos.y = u.origin.y - sign(u.dir.y) * hf.y;
                    } else if (ad.x >= ad.z) {
                      p.pos.x = u.origin.x - sign(u.dir.x) * hf.x;
                    } else {
                      p.pos.z = u.origin.z - sign(u.dir.z) * hf.z;
                    }
                  }
                  respawned = true;
                } else {
                  // Surface normal from depth neighbours, unprojected.
                  let p0 = sp;
                  let d1 = loadDepth(px + vec2i(2, 0));
                  let d2 = loadDepth(px + vec2i(0, 2));
                  var nrm = vec3f(0.0, 1.0, 0.0);
                  if (d1 > 0.0 && d1 < 1.0 && d2 > 0.0 && d2 < 1.0) {
                    let p1 = unproject(vec2f(px + vec2i(2, 0)), d1);
                    let p2 = unproject(vec2f(px + vec2i(0, 2)), d2);
                    let cr = cross(p1 - p0, p2 - p0);
                    if (length(cr) > 1e-9) { nrm = normalize(cr); }
                  }
                  if (dot(nrm, vel) > 0.0) { nrm = -nrm; }
                  let vn = dot(vel, nrm);
                  let tangential = vel - nrm * vn;
                  vel = (tangential * (1.0 - u.hit.z) - nrm * vn * u.hit.y);
                  pos = p.pos.xyz; // stay put this step: never tunnel in
                  // Rest mode: once the bounce has bled the speed off, the
                  // particle COMES TO REST — freeze it where it lies.
                  if (u.hit.x > 2.5 && length(vel) < 0.3) {
                    vel = vec3f(0.0);
                    p.ext.w = p.pos.w;
                  }
                }
              }
            }
          }
        }
      }
      // WRAP: fold the position back into a box around the emitter origin,
      // torus-style — the infinite-field illusion. Move the emitter with
      // the camera and a bounded pool covers any world size: particles
      // recycle across the trailing edge, fallers wrap back to the top.
      if (u.wrapv.w > 0.5 && !respawned) {
        let ext = u.wrapv.xyz;
        let half = ext * 0.5;
        let rel = pos - u.origin.xyz + half;
        let safe = max(ext, vec3f(1e-5));
        let folded = u.origin.xyz + (fract(rel / safe) * safe - half);
        pos = select(pos, folded, ext > vec3f(0.0));
      }
      if (!respawned) {
        p.vel = vec4f(vel, p.vel.w);
        p.pos = vec4f(pos, p.pos.w);
      }
    }
  }
  // ALPHA emitters (screen.w bit 1) draw in STABLE POOL ORDER: compaction
  // via atomicAdd is nondeterministic across workgroups, so unsorted
  // translucency re-composites in a DIFFERENT order every frame — dense
  // alpha smoke shimmers/flickers. Stable mode maps alive[i] = i and draws
  // the whole pool (dead slots emit degenerate clipped quads — no
  // fragments); additive emitters keep the tight compacted draw (additive
  // blending is order-independent). args.live carries the true count.
  if (p.vel.w > 0.0 && p.pos.w < p.vel.w) {
    atomicAdd(&args.live, 1u);
    if (u.screen.w < 1.5) {
      let slot = atomicAdd(&args.instanceCount, 1u);
      alive[slot] = i;
    }
  }
  if (u.screen.w >= 1.5) { alive[i] = i; }
  parts[i] = p;
}

@compute @workgroup_size(1)
fn reset() {
  atomicStore(&args.instanceCount, select(0u, u32(u.shape.w), u.screen.w >= 1.5));
  atomicStore(&args.live, 0u);
}
`;
}

/** Assemble the render shader (camera-facing/velocity-stretched quads with
 * ramp-over-life, twinkle, soft depth fade). Pure string work. */
export function buildGpuParticleRenderWGSL(ms: boolean): string {
  const depthDecl = ms
    ? 'var depthTex: texture_depth_multisampled_2d;'
    : 'var depthTex: texture_depth_2d;';
  return /* wgsl */ `
struct U {
  viewProj: mat4x4f,
  camPos: vec4f,
  fogColor: vec4f,
  params: vec4f,        // fogNear, fogFar, fogOn, TIME
  lightDir: vec4f,
  camRight: vec4f,
  camUp: vec4f,
}
${COMMON_WGSL}
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uvn: vec2f,
  @location(1) uv: vec2f,
  @location(2) color: vec4f,
  @location(3) world: vec3f,
  @location(4) viewDist: f32,
  @location(5) rest: f32,          // 1 = lying on geometry (disables soft fade)
}
@group(0) @binding(0) var<uniform> w: U;
@group(0) @binding(1) var<uniform> u: EU;
@group(0) @binding(2) var<storage, read> parts: array<P>;
@group(0) @binding(3) var<storage, read> alive: array<u32>;
@group(0) @binding(4) var samp: sampler;
@group(0) @binding(5) var tex: texture_2d<f32>;
@group(0) @binding(6) ${depthDecl}

fn rampAt(t: f32) -> vec4f {
  let n = max(1.0, u.ramp[7].w);              // stop count stashed in the last slot's w
  let ci = clamp(t, 0.0, 1.0) * (n - 1.0);
  let i0 = u32(clamp(floor(ci), 0.0, 6.0));
  let i1 = min(i0 + 1u, u32(n - 1.0));
  let c0 = u.ramp[i0];
  let c1 = u.ramp[i1];
  return vec4f(mix(c0.rgb, c1.rgb, ci - floor(ci)), 1.0);
}

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let p = parts[alive[ii]];
  // Stable-order draws cover the WHOLE pool — dead slots become degenerate
  // clipped quads (z > w) and never reach the fragment stage.
  if (p.vel.w <= 0.0 || p.pos.w >= p.vel.w) {
    var dead: VSOut;
    dead.pos = vec4f(0.0, 0.0, 2.0, 1.0);
    return dead;
  }
  let t = clamp(p.pos.w / max(0.001, p.vel.w), 0.0, 1.0);
  // Rested particles freeze their animation clock at the rest age and
  // blend (over 0.2s) from camera-facing to LYING FLAT in the world plane.
  let rested = p.ext.w > 0.0;
  let effAge = select(p.pos.w, p.ext.w, rested);
  let restK = select(0.0, clamp((p.pos.w - p.ext.w) / 0.2, 0.0, 1.0), rested);
  var size = p.ext.x * mix(1.0, u.look.x, t);
  var a = u.look.z;
  // fade = the FRACTION of life over which alpha eases out at the end
  // (1 = the whole life, the old linear behaviour; 0.12 = only the last 12%).
  if (u.look.y > 0.0) { a *= clamp((1.0 - t) / u.look.y, 0.0, 1.0); }
  if (u.look.w > 0.0) {
    a *= 1.0 - u.look.w * (0.5 + 0.5 * sin(u.softp.y * 11.0 + p.ext.y * 271.0));
  }
  var rgb = u.ramp[0].rgb;
  if (u.look2.w > 1.5) {
    // palette: a per-particle stop picked by seed
    let n = max(1.0, u.ramp[7].w);
    rgb = u.ramp[u32(min(p.ext.y * n, n - 1.0))].rgb;
  } else if (u.look2.w > 0.5) {
    rgb = rampAt(t).rgb;
  }
  // TUMBLE: fake the quad turning over in 3D — squash its OWN across-axis
  // on a per-particle cosine (thin when edge-on) and dim it slightly. The
  // squash happens BEFORE the spin rotation, so it reads as the petal
  // flipping about its long axis however it has spun.
  var tsy = 1.0;
  if (u.flut.z > 0.0) {
    let tc = cos((effAge * u.flut.w + p.ext.y * 7.0) * 6.2831853);
    tsy = mix(1.0, max(0.12, abs(tc)), u.flut.z);
    rgb *= mix(mix(1.0, 0.72 + 0.28 * abs(tc), u.flut.z), 1.0, restK);
    tsy = mix(tsy, 1.0, restK);        // a resting petal opens fully flat
  }
  let c01 = vec2f(f32(vi & 1u), f32(vi >> 1u));
  var off = c01 - 0.5;
  off = vec2f(off.x, off.y * tsy);
  let rot = p.ext.z * effAge;
  let cr = cos(rot);
  let sr = sin(rot);
  off = vec2f(off.x * cr - off.y * sr, off.x * sr + off.y * cr);
  var world: vec3f;
  let speed = length(p.vel.xyz);
  if (u.look2.z > 0.0 && speed > 0.05) {
    // Velocity stretch: align the quad's x-axis with the velocity's
    // screen-parallel component and elongate by speed.
    let viewDir = normalize(p.pos.xyz - w.camPos.xyz);
    var axisX = p.vel.xyz - viewDir * dot(p.vel.xyz, viewDir);
    if (length(axisX) < 1e-5) { axisX = w.camRight.xyz; }
    axisX = normalize(axisX);
    let axisY = normalize(cross(viewDir, axisX));
    let raw = c01 - 0.5;
    let stretchLen = size * (1.0 + u.look2.z * speed);
    world = p.pos.xyz + (axisX * raw.x * stretchLen + axisY * raw.y * tsy * size) * 2.0;
  } else {
    let facing = p.pos.xyz + (w.camRight.xyz * off.x + w.camUp.xyz * off.y) * (size * 2.0);
    // Rested: blend to a quad lying FLAT in the world XZ plane (keeping its
    // frozen in-plane rotation) — a petal on the ground, not a billboard.
    let flat = p.pos.xyz + vec3f(off.x, 0.0, off.y) * (size * 2.0);
    world = mix(facing, flat, restK);
  }
  var out: VSOut;
  out.pos = w.viewProj * vec4f(world, 1.0);
  out.uvn = c01;
  out.uv = vec2f(mix(u.uv.x, u.uv.z, c01.x), mix(u.uv.y, u.uv.w, 1.0 - c01.y));
  out.color = vec4f(rgb, a);
  out.world = world;
  out.viewDist = out.pos.w;
  out.rest = restK;
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  // in.pos is the @builtin(position) — fragment coordinates in this stage.
  let tx = textureSample(tex, samp, in.uv);   // unconditional: uniform control flow
  let dd = length(in.uvn - 0.5) * 2.0;
  var rgb = in.color.rgb;
  var a = in.color.a;
  // screen.w packs two bits: 1 = textured frame, 2 = stable draw order.
  if ((u32(u.screen.w + 0.5) & 1u) == 1u) {
    rgb *= tx.rgb;
    a *= tx.a;
  } else {
    let crisp = 1.0 - smoothstep(0.9, 1.0, dd);
    let glow = exp(-dd * dd * 5.0) * smoothstep(1.0, 0.7, dd);
    a *= mix(crisp, glow, clamp(u.look2.y, 0.0, 1.0));
  }
  // SOFT PARTICLES: fade where the quad nears scene depth (this frame's
  // opaque depth, bound read-only in the translucent pass).
  if (u.softp.x > 0.0) {
    let d = textureLoad(depthTex, vec2i(in.pos.xy), 0);
    if (d < 1.0) {
      let sceneDist = u.softp.w / (u.softp.z + d);
      // Rested particles LIE ON the geometry — soft fade would erase them.
      a *= mix(clamp((sceneDist - in.viewDist) / u.softp.x, 0.0, 1.0), 1.0, in.rest);
    }
  }
  let add = u.look2.x;
  if (w.params.z > 0.5) {
    let f = smoothstep(w.params.x, w.params.y, distance(w.camPos.xyz, in.world));
    rgb = mix(rgb, w.fogColor.rgb * (1.0 - add), f);
  }
  return vec4f(rgb * a, a * (1.0 - add));
}
`;
}

// ---------------------------------------------------------------------------
// The emitter surface — Emit3dOptions vocabulary, persistent + live-mutable.

export interface GpuEmitterOptions {
  x?: number; y?: number; z?: number;
  /** Pool size — the max simultaneously alive (default 65536). The pool is a
   * RING: if rate × life exceeds it, the oldest particles are recycled. */
  capacity?: number;
  /** Continuous spawn rate, particles/second (default 0 — burst-driven). */
  rate?: number;
  /** Emission cone axis (any length; omit = every direction). */
  dir?: { x?: number; y?: number; z?: number };
  /** Cone full angle around dir, radians (default 2π). */
  spread?: number;
  /** RADIAL emission: velocity points AWAY from the emitter origin — pair
   * with `ring`/`spawnRadius`/`box` spawn shapes for shockwaves, novas and
   * explosion shells (overrides dir/spread). */
  radial?: boolean;
  speed?: number; speedVar?: number;
  /** Jitter the spawn point within this sphere radius. */
  spawnRadius?: number;
  /** Spawn uniformly inside a box of these extents. */
  box?: { w?: number; h?: number; d?: number };
  /** Spawn on a horizontal (XZ) ring of this radius. */
  ring?: number;
  life?: number; lifeVar?: number;
  size?: number; sizeVar?: number;
  /** Size over life — true shrinks to 0, false constant, a number = final
   * fraction (>1 grows). Default true. */
  shrink?: boolean | number;
  /** Alpha out at the end of life: true = over the WHOLE life (linear),
   * false = never, a number = only over that final FRACTION of life
   * (0.12 = opaque until the last 12% — petals/leaves/debris want this;
   * a whole-life fade leaves most of the pool translucent). Default true. */
  fade?: boolean | number;
  /** Colour ramp over life ('fire', 'smoke', … or hex stops). */
  ramp?: RampName | string[];
  color?: string;
  /** A palette picked per particle (mutually exclusive with ramp). */
  colors?: string[];
  alpha?: number;
  twinkle?: number;
  /** Additive blend. DEFAULT TRUE here (unlike the CPU pool): a 100k pool is
   * unsorted, and additive is the only order-independent look. */
  add?: boolean;
  /** Untextured falloff: 1 = gaussian glow puff (default), 0 = crisp disc. */
  soft?: number;
  /** Atlas frame instead of the disc (tinted by color/ramp). */
  frame?: number;
  /** Random spin up to ±spin rad/s. */
  spin?: number;
  /** Velocity stretch: elongate the quad along motion by stretch × speed
   * (motion-blurred sparks). Default 0. */
  stretch?: number;
  /** FLUTTER: the falling-leaf rock — horizontal oscillating acceleration,
   * per-particle direction + phase (petals, leaves, paper, feathers).
   * Units/s²; try 1.5–3 with gentle gravity. Default 0. */
  flutter?: number;
  /** Flutter oscillation frequency, cycles/s (default 0.7). */
  flutterFreq?: number;
  /** TUMBLE 0..1: fake the quad turning over in 3D — its across-axis
   * squashes on a per-particle cosine (thin + dimmed when edge-on).
   * Petals/leaves/confetti read flat without it. Default 0. */
  tumble?: number;
  /** Tumble rate, turns/s (default 0.6). */
  tumbleSpeed?: number;
  /** Soft-particle fade distance in world units (default 0.25; 0 = off). */
  softFade?: number;
  /** WRAP: fold particle positions torus-style into a box of these extents
   * centred on the emitter origin (true = the spawn `box` extents). THE
   * large-area recipe: size the box a little past the fog distance, move
   * the emitter with the camera every frame, and a bounded pool reads as
   * weather over an unlimited world — particles recycle across the
   * trailing edge; fallers wrap back to the top (infinite rain from one
   * burst). A zero extent leaves that axis unwrapped. Rested particles
   * never wrap (they're lying on geometry). */
  wrap?: boolean | { w?: number; h?: number; d?: number };
  /** The force stack (data — see GpuForce). Live-mutable. */
  forces?: GpuForce[];
  /** DEPTH-BUFFER collision: particles bounce off (or die on) whatever is
   * on screen. true = { bounce: 0.5 }. `rest: true` = once a bounce has
   * bled the speed off, the particle COMES TO REST where it lies: the sim
   * freezes it, spin/tumble stop, and it settles FLAT in the world plane
   * (petals and snow on the ground) until its life fades out.
   * `respawn: true` = on contact the particle is instantly REBORN via the
   * spawn init — the infinite-rain mode: one burst + wrap recycles
   * forever, nothing accumulates, nothing bounces. Directional emitters
   * re-enter at the box face OPPOSITE `dir` (rain: the top face), keeping
   * the sky's influx uniform — a volume rebirth would paint the ground's
   * height map into the sky's rain density (columns over tall objects
   * cycle at different rates). Omni emitters rebirth in the volume.
   * `thickness` = contact distance in world units: a hit needs the
   * particle within this true 3D distance of the visible surface point
   * (not merely close along the view ray — that over-triggers at grazing
   * angles). */
  collide?: boolean | { bounce?: number; friction?: number; kill?: boolean; rest?: boolean; respawn?: boolean; thickness?: number };
}

interface EmitterGpuRes {
  parts: GPUBuffer;
  alive: GPUBuffer;
  args: GPUBuffer;
  uniform: GPUBuffer;
  staging: GPUBuffer[];
  stagingBusy: boolean[];
  computeBind: GPUBindGroup | null;
  renderBind: GPUBindGroup | null;
  boundDepth: GPUTextureView | null;
  boundTex: GPUTextureView | null;
}

/** A persistent GPU emitter. Mutate the public fields freely — the uniform is
 * repacked every frame. `kill()` releases the pool. */
export class GpuEmitter {
  x: number; y: number; z: number;
  /** Particles per second (live). */
  rate: number;
  /** The full option surface — mutate anything (forces included). */
  readonly opts: GpuEmitterOptions;
  readonly capacity: number;
  /** Alive count, ~2 frames stale (async readback). */
  alive = 0;
  dead = false;

  /** @internal */ cursor = 0;
  /** @internal */ acc = 0;
  /** @internal */ burstN = 0;
  /** @internal */ res: EmitterGpuRes | null = null;
  /** @internal */ seedCounter = (Math.random() * 0xffffffff) >>> 0;

  constructor(opts: GpuEmitterOptions) {
    this.opts = opts;
    this.x = opts.x ?? 0; this.y = opts.y ?? 0; this.z = opts.z ?? 0;
    this.rate = opts.rate ?? 0;
    this.capacity = Math.max(64, Math.min(1 << 21, Math.ceil(opts.capacity ?? 65536)));
  }

  /** Queue an immediate one-shot spawn of `count` particles this frame. */
  burst(count: number): void {
    this.burstN += Math.max(0, count);
  }

  /** Release the emitter and its GPU pool. */
  kill(): void {
    this.dead = true;
  }
}

// ---------------------------------------------------------------------------
// The system: pipelines shared across emitters; per-emitter buffers/binds.

const WG = 64;

export class GpuParticles {
  private emitters: GpuEmitter[] = [];
  private device!: GPUDevice;
  private computePipeline!: GPUComputePipeline;
  private resetPipeline!: GPUComputePipeline;
  private renderPipeline!: GPURenderPipeline;
  private computeLayout!: GPUBindGroupLayout;
  private renderLayout!: GPUBindGroupLayout;
  private sampler!: GPUSampler;
  private uniformScratch = new Float32Array(EU_TOTAL);
  private depthTex: GPUTexture | null = null;
  private depthView: GPUTextureView | null = null;
  private pendingMaps: Array<{ e: GpuEmitter; r: EmitterGpuRes; si: number }> = [];

  constructor(
    device: GPUDevice,
    private format: GPUTextureFormat,
    private sampleCount: number,
    private filter: GPUFilterMode,
  ) {
    this.rebuild(device);
  }

  /** Live emitters (dead ones are reaped in compute()). */
  get list(): readonly GpuEmitter[] {
    return this.emitters;
  }

  /** Total alive particles across emitters (readback — ~2 frames stale). */
  get count(): number {
    let n = 0;
    for (const e of this.emitters) n += e.alive;
    return n;
  }

  emitter(opts: GpuEmitterOptions): GpuEmitter {
    const e = new GpuEmitter(opts);
    this.allocate(e);
    this.emitters.push(e);
    return e;
  }

  /** (Re)create pipelines; per-emitter buffers are re-allocated too (their
   * particle state is GPU-only and simply restarts — device loss already
   * blanks the screen for a frame). */
  rebuild(device: GPUDevice): void {
    this.device = device;
    const ms = this.sampleCount > 1;
    this.computeLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'storage' } },
        { binding: 2, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'storage' } },
        { binding: 3, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'storage' } },
        { binding: 4, visibility: BITS.STAGE_COMPUTE, texture: { sampleType: 'depth', multisampled: ms } },
      ],
    });
    this.renderLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 2, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 3, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 4, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
        { binding: 5, visibility: BITS.STAGE_FRAGMENT, texture: {} },
        { binding: 6, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'depth', multisampled: ms } },
      ],
    });
    const computeModule = shaderModule(device, buildGpuParticleComputeWGSL(ms), 'GpuParticles compute');
    const renderModule = shaderModule(device, buildGpuParticleRenderWGSL(ms), 'GpuParticles render');
    const computePL = device.createPipelineLayout({ bindGroupLayouts: [this.computeLayout] });
    this.computePipeline = device.createComputePipeline({ layout: computePL, compute: { module: computeModule, entryPoint: 'cs' } });
    this.resetPipeline = device.createComputePipeline({ layout: computePL, compute: { module: computeModule, entryPoint: 'reset' } });
    this.renderPipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.renderLayout] }),
      vertex: { module: renderModule, entryPoint: 'vs' },
      fragment: {
        module: renderModule,
        entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-strip' },
      multisample: { count: this.sampleCount },
    });
    this.sampler = device.createSampler({ magFilter: this.filter, minFilter: this.filter });
    for (const e of this.emitters) this.allocate(e);
  }

  private allocate(e: GpuEmitter): void {
    const device = this.device;
    const parts = device.createBuffer({ size: e.capacity * P_FLOATS * 4, usage: BITS.STORAGE });
    const alive = device.createBuffer({ size: e.capacity * 4, usage: BITS.STORAGE });
    // 32 bytes: 16 of drawIndirect args + the live-count stat + padding.
    const args = device.createBuffer({ size: 32, usage: BITS.STORAGE | BITS.INDIRECT | BITS.COPY_DST | BITS.COPY_SRC });
    device.queue.writeBuffer(args, 0, new Uint32Array([4, 0, 0, 0, 0, 0, 0, 0]));
    const uniform = device.createBuffer({ size: EU_TOTAL * 4, usage: BITS.UNIFORM | BITS.COPY_DST });
    e.res = {
      parts, alive, args, uniform,
      staging: [
        device.createBuffer({ size: 32, usage: BITS.MAP_READ | BITS.COPY_DST }),
        device.createBuffer({ size: 32, usage: BITS.MAP_READ | BITS.COPY_DST }),
      ],
      stagingBusy: [false, false],
      computeBind: null,
      renderBind: null,
      boundDepth: null,
      boundTex: null,
    };
    e.cursor = 0;
    e.acc = 0;
  }

  private release(e: GpuEmitter): void {
    const r = e.res;
    if (!r) return;
    r.parts.destroy(); r.alive.destroy(); r.args.destroy(); r.uniform.destroy();
    for (const s of r.staging) s.destroy();
    e.res = null;
  }

  /** Pack the per-frame uniform for one emitter (pure-ish: writes scratch). */
  private packUniform(
    e: GpuEmitter, dt: number, time: number, spawn0: number, spawnN: number, seed: number,
    depthW: number, depthH: number, prevVP: Mat4 | null, prevInv: Mat4 | null,
    projA: number, projB: number, atlas: Atlas,
  ): Float32Array {
    const u = this.uniformScratch;
    u.fill(0);
    const o = e.opts;
    u[O.spawn] = spawn0; u[O.spawn + 1] = spawnN; u[O.spawn + 2] = seed; u[O.spawn + 3] = dt;
    u[O.origin] = e.x; u[O.origin + 1] = e.y; u[O.origin + 2] = e.z; u[O.origin + 3] = o.spawnRadius ?? 0;
    const d = o.dir;
    u[O.dir] = d?.x ?? 0; u[O.dir + 1] = d?.y ?? 0; u[O.dir + 2] = d?.z ?? 0;
    u[O.dir + 3] = o.radial ? -1 : o.spread ?? Math.PI * 2;
    u[O.box] = o.box?.w ?? 0; u[O.box + 1] = o.box?.h ?? 0; u[O.box + 2] = o.box?.d ?? 0;
    u[O.box + 3] = o.ring ?? 0;
    const speed = o.speed ?? 3;
    u[O.motion] = speed; u[O.motion + 1] = o.speedVar ?? speed * 0.4;
    u[O.motion + 2] = o.life ?? 2; u[O.motion + 3] = o.lifeVar ?? (o.life ?? 2) * 0.3;
    const size = o.size ?? 0.06;
    u[O.shape] = size; u[O.shape + 1] = o.sizeVar ?? size * 0.4;
    u[O.shape + 2] = o.spin ?? 0; u[O.shape + 3] = e.capacity;
    u[O.look] = typeof o.shrink === 'number' ? Math.max(0, o.shrink) : (o.shrink ?? true) ? 0 : 1;
    u[O.look + 1] = typeof o.fade === 'number' ? Math.min(1, Math.max(0, o.fade)) : (o.fade ?? true) ? 1 : 0;
    u[O.look + 2] = o.alpha ?? 1;
    u[O.look + 3] = o.twinkle ?? 0;
    u[O.look2] = (o.add ?? true) ? 1 : 0;
    u[O.look2 + 1] = o.soft ?? 1;
    u[O.look2 + 2] = o.stretch ?? 0;
    u[O.look2 + 3] = o.ramp ? 1 : o.colors ? 2 : 0;
    const frame = atlas.frames[o.frame != null && o.frame >= 0 ? o.frame : 0];
    if (frame) { u[O.uv] = frame.u0; u[O.uv + 1] = frame.v0; u[O.uv + 2] = frame.u1; u[O.uv + 3] = frame.v1; }
    const col = o.collide === true ? {} : o.collide || null;
    // Collision waits for a previous frame's matrices (frame 1 has none).
    // Modes: 0 off, 1 bounce, 2 kill, 3 bounce + come-to-rest, 4 respawn.
    u[O.hit] = col && prevVP ? (col.kill ? 2 : col.respawn ? 4 : col.rest ? 3 : 1) : 0;
    u[O.hit + 1] = col?.bounce ?? 0.5;
    u[O.hit + 2] = col?.friction ?? 0.1;
    u[O.hit + 3] = col?.thickness ?? 0.5;
    u[O.softp] = o.softFade ?? 0.25;
    u[O.softp + 1] = time;
    u[O.softp + 2] = projA;
    u[O.softp + 3] = projB;
    const forces = o.forces ?? [];
    u[O.screen] = depthW; u[O.screen + 1] = depthH;
    u[O.screen + 2] = Math.min(MAX_GPU_FORCES, forces.length);
    // bit 0 = textured frame; bit 1 = STABLE draw order (alpha emitters:
    // compaction order is nondeterministic and unsorted alpha shimmers).
    u[O.screen + 3] = (o.frame != null && o.frame >= 0 ? 1 : 0) + ((o.add ?? true) ? 0 : 2);
    u[O.flut] = o.flutter ?? 0;
    u[O.flut + 1] = o.flutterFreq ?? 0.7;
    u[O.flut + 2] = Math.min(1, Math.max(0, o.tumble ?? 0));
    u[O.flut + 3] = o.tumbleSpeed ?? 0.6;
    if (o.wrap) {
      const wr = o.wrap === true ? o.box ?? {} : o.wrap;
      u[O.wrapv] = wr.w ?? 0; u[O.wrapv + 1] = wr.h ?? 0; u[O.wrapv + 2] = wr.d ?? 0;
      u[O.wrapv + 3] = 1;
    }
    u.set(packForces(forces), O.forces);
    if (prevVP) u.set(prevVP, O.prevVP);
    if (prevInv) u.set(prevInv, O.prevInv);
    // Ramp slots: ramp stops, or the palette, or the single colour. The stop
    // count rides in slot 7's w (slot 7's own colour still works — its rgb
    // is intact and w is never read as alpha).
    const stops = o.ramp ? resolveRamp(o.ramp)
      : o.colors ? o.colors.map((c) => rgba(c))
        : [rgba(o.color ?? '#ffffff')];
    const n = Math.min(8, stops.length);
    for (let i = 0; i < n; i++) {
      u[O.ramp + i * 4] = stops[i][0];
      u[O.ramp + i * 4 + 1] = stops[i][1];
      u[O.ramp + i * 4 + 2] = stops[i][2];
      u[O.ramp + i * 4 + 3] = stops[i][3];
    }
    u[O.ramp + 7 * 4 + 3] = n;
    return u;
  }

  /**
   * Encode this frame's sim: per emitter — reset the indirect args (encoder-
   * ordered, so the pre-reset count can be copied out for the readback),
   * repack + upload the uniform, dispatch the update kernel. Runs BEFORE the
   * render passes; collision reads `depth` (last frame's content).
   */
  compute(
    encoder: GPUCommandEncoder, dt: number, time: number,
    depth: GPUTexture, prevVP: Mat4 | null, prevInv: Mat4 | null,
    projA: number, projB: number, atlas: Atlas,
  ): void {
    // Reap dead emitters first (their buffers go with them).
    for (let i = this.emitters.length - 1; i >= 0; i--) {
      if (this.emitters[i].dead) {
        this.release(this.emitters[i]);
        this.emitters.splice(i, 1);
      }
    }
    if (!this.emitters.length) return;
    // One view per texture identity (Game recreates the texture on resize —
    // view identity tracks that, so bind groups only remake when they must).
    if (this.depthTex !== depth) {
      this.depthTex = depth;
      this.depthView = depth.createView();
      for (const em of this.emitters) {
        if (em.res) { em.res.computeBind = null; em.res.renderBind = null; }
      }
    }
    const depthView = this.depthView!;
    for (const e of this.emitters) {
      const r = e.res!;
      // Spawn accounting: fractional rate accumulation + queued bursts.
      e.acc += e.rate * dt + e.burstN;
      e.burstN = 0;
      let n = Math.floor(e.acc);
      e.acc -= n;
      if (n > e.capacity) n = e.capacity;
      const spawn0 = e.cursor;
      e.cursor = (e.cursor + n) % e.capacity;
      e.seedCounter = (e.seedCounter + 1) >>> 0;
      const u = this.packUniform(
        e, dt, time, spawn0, n, pcg(e.seedCounter),
        depth.width, depth.height, prevVP, prevInv, projA, projB, atlas,
      );
      this.device.queue.writeBuffer(r.uniform, 0, u.buffer, 0, EU_TOTAL * 4);
      if (!r.computeBind || r.boundDepth !== depthView) {
        r.computeBind = this.device.createBindGroup({
          layout: this.computeLayout,
          entries: [
            { binding: 0, resource: { buffer: r.uniform } },
            { binding: 1, resource: { buffer: r.parts } },
            { binding: 2, resource: { buffer: r.alive } },
            { binding: 3, resource: { buffer: r.args } },
            { binding: 4, resource: depthView },
          ],
        });
        r.boundDepth = depthView;
        r.renderBind = null; // render bind holds the depth too
      }
      // Copy LAST frame's alive count out before the reset (encoder order).
      // The mapAsync happens in afterSubmit() — a buffer with a pending map
      // may not appear in a submit, so mapping here would poison the frame.
      const si = r.stagingBusy[0] ? (r.stagingBusy[1] ? -1 : 1) : 0;
      if (si >= 0) {
        encoder.copyBufferToBuffer(r.args, 0, r.staging[si], 0, 32);
        r.stagingBusy[si] = true;
        this.pendingMaps.push({ e, r, si });
      }
      const pass = encoder.beginComputePass();
      pass.setPipeline(this.resetPipeline);
      pass.setBindGroup(0, r.computeBind);
      pass.dispatchWorkgroups(1);
      pass.setPipeline(this.computePipeline);
      pass.setBindGroup(0, r.computeBind);
      pass.dispatchWorkgroups(Math.ceil(e.capacity / WG));
      pass.end();
    }
  }

  /** Draw every emitter into the (translucent) pass — one drawIndirect each. */
  render(pass: GPURenderPassEncoder, worldUniforms: GPUBuffer, atlasView: GPUTextureView | null): void {
    if (!this.emitters.length || !atlasView) return;
    let set = false;
    for (const e of this.emitters) {
      const r = e.res!;
      if (!r.boundDepth) continue; // compute hasn't run yet this device
      if (!r.renderBind || r.boundTex !== atlasView) {
        r.renderBind = this.device.createBindGroup({
          layout: this.renderLayout,
          entries: [
            { binding: 0, resource: { buffer: worldUniforms } },
            { binding: 1, resource: { buffer: r.uniform } },
            { binding: 2, resource: { buffer: r.parts } },
            { binding: 3, resource: { buffer: r.alive } },
            { binding: 4, resource: this.sampler },
            { binding: 5, resource: atlasView },
            { binding: 6, resource: r.boundDepth },
          ],
        });
        r.boundTex = atlasView;
      }
      if (!set) { pass.setPipeline(this.renderPipeline); set = true; }
      pass.setBindGroup(0, r.renderBind);
      pass.drawIndirect(r.args, 0);
    }
  }

  /** Kick off the alive-count readbacks — call AFTER queue.submit() (a
   * pending map on a buffer inside a submit is a validation error). */
  afterSubmit(): void {
    for (const m of this.pendingMaps) {
      const buf = m.r.staging[m.si];
      void buf.mapAsync(1 /* GPUMapMode.READ */).then(() => {
        // word 4 = the live-count stat (instanceCount is the whole pool in
        // stable-order mode, so it can't serve as the count).
        m.e.alive = new Uint32Array(buf.getMappedRange())[4];
        buf.unmap();
        m.r.stagingBusy[m.si] = false;
      }).catch(() => { m.r.stagingBusy[m.si] = false; });
    }
    this.pendingMaps.length = 0;
  }

  /** Kill everything (world teardown). */
  clear(): void {
    for (const e of this.emitters) {
      this.release(e);
      e.dead = true;
    }
    this.emitters = [];
  }
}

// Layout self-checks used by dist tests (the WGSL struct and the pack offsets
// must agree; drift here is invisible until particles misbehave).
export const GPU_PARTICLE_LAYOUT = { P_FLOATS, EU_TOTAL, offsets: O } as const;
