// GOD RAYS — screen-space light shafts (Rich Environments E4). The classic
// radial-march: at HALF res, every pixel walks toward the sun's screen
// position sampling the OPAQUE DEPTH — sky pixels (depth ≈ 1) contribute
// light, geometry blocks it, and the decayed sum becomes shafts streaming
// past whatever occludes the sun. Composites ADDITIVELY into the scene
// (the SSAO pass's structure, plus instead of times).
//
// Fed by the world's sun (world.sunScreen — the sky's day/night dial moves
// and colours the shafts for free). world.rays(true) to enable; cost is one
// half-res pass of 28 depth taps per pixel.
import { BITS, shaderModule } from './gpu.js';
import { DEPTH_FORMAT } from './batch.js';

export interface RaysOptions {
  /** Overall shaft brightness (default 0.55). */
  strength?: number;
  /** Per-step energy falloff along the march (default 0.94). */
  decay?: number;
}

const UNIFORM_FLOATS = 12;

function raysWGSL(ms: boolean): string {
  const depthDecl = ms ? 'var depthTex: texture_depth_multisampled_2d;' : 'var depthTex: texture_depth_2d;';
  return /* wgsl */ `
struct RU {
  sun: vec4f,     // sun uv (0..1), intensity, decay
  info: vec4f,    // halfW, halfH, fullW, fullH
  color: vec4f,   // sun rgb + aspect
}
@group(0) @binding(0) var<uniform> ru: RU;
@group(0) @binding(1) ${depthDecl}

struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var out: VSOut;
  out.pos = vec4f(p[vi], 0.0, 1.0);
  out.uv = vec2f(p[vi].x * 0.5 + 0.5, 0.5 - p[vi].y * 0.5);
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let sunUV = ru.sun.xy;
  // March from THIS pixel toward the sun. THE MASK IS THE SUN REGION, not
  // "any sky": a sample only pours in light if it is sky AND near the sun
  // — that is what turns a diffuse wash into defined BEAMS radiating
  // through the gaps in a silhouette (the first cut accumulated all sky
  // along the path and vanished into the already-bright horizon).
  let STEPS = 28.0;
  let delta = (sunUV - in.uv) / STEPS;
  var p = in.uv;
  var acc = 0.0;
  var w = 1.0;
  var norm = 0.0;
  for (var i = 0; i < 28; i = i + 1) {
    p += delta;
    let px = vec2i(clamp(p, vec2f(0.0), vec2f(0.9999)) * ru.info.zw);
    let d = textureLoad(depthTex, px, 0);
    let sd = length((p - sunUV) * vec2f(ru.color.w, 1.0));
    acc += step(0.99995, d) * smoothstep(0.42, 0.05, sd) * w;
    norm += w;
    w *= ru.sun.w;
  }
  // Radial falloff: shafts live NEAR the sun, not across the whole frame.
  let dist = length((in.uv - sunUV) * vec2f(ru.color.w, 1.0));
  let fall = smoothstep(1.05, 0.12, dist);
  return vec4f(acc / max(norm, 1e-4) * ru.sun.z * fall, 0.0, 0.0, 1.0);
}
`;
}

const COMPOSITE_WGSL = /* wgsl */ `
struct CU { color: vec4f }   // sun rgb + unused
@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var rays: texture_2d<f32>;
@group(0) @binding(2) var<uniform> cu: CU;

struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var out: VSOut;
  out.pos = vec4f(p[vi], 0.0, 1.0);
  out.uv = vec2f(p[vi].x * 0.5 + 0.5, 0.5 - p[vi].y * 0.5);
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let r = textureSample(rays, samp, in.uv).r;
  return vec4f(cu.color.rgb * r, 0.0);   // additive: dst + src
}
`;

export class RaysPass {
  /** Live-tunable, read every render. */
  readonly opts: Required<RaysOptions> = { strength: 0.9, decay: 0.94 };
  /** Off by default — render()/composite() no-op until switched on. */
  enabled = false;

  private device!: GPUDevice;
  private marchPipeline!: GPURenderPipeline;
  private marchPipelineMS!: GPURenderPipeline;
  private marchLayout!: GPUBindGroupLayout;
  private marchLayoutMS!: GPUBindGroupLayout;
  private compPipeline!: GPURenderPipeline;
  private compLayout!: GPUBindGroupLayout;
  private sampler!: GPUSampler;
  private uniforms!: GPUBuffer;
  private compUniforms!: GPUBuffer;
  private target: GPUTexture | null = null;
  private compBind: GPUBindGroup | null = null;
  private rendered = false;
  private data = new Float32Array(UNIFORM_FLOATS);

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.rebuild(device);
  }

  /** Encode the shaft march (half res). `sun` is the world's projected sun:
   * uv in [0,1], intensity already faded for off-screen / night / storm. */
  render(
    encoder: GPUCommandEncoder, depth: GPUTexture,
    sun: { x: number; y: number; intensity: number; color: [number, number, number] },
    canvasW: number, canvasH: number,
  ): void {
    this.rendered = false;
    if (!this.enabled || sun.intensity <= 0.001) return;
    const w = Math.max(1, canvasW >> 1), h = Math.max(1, canvasH >> 1);
    if (!this.target || this.target.width !== w || this.target.height !== h) {
      this.target?.destroy();
      this.target = this.device.createTexture({
        size: { width: w, height: h },
        format: 'r8unorm',
        usage: BITS.RENDER_ATTACHMENT | BITS.TEXTURE_BINDING,
      });
      this.compBind = null;
    }
    const d = this.data;
    d.set([sun.x, sun.y, sun.intensity * this.opts.strength, this.opts.decay], 0);
    d.set([w, h, canvasW, canvasH], 4);
    d.set([sun.color[0], sun.color[1], sun.color[2], canvasW / canvasH], 8);
    this.device.queue.writeBuffer(this.uniforms, 0, d);
    this.device.queue.writeBuffer(this.compUniforms, 0, new Float32Array([sun.color[0], sun.color[1], sun.color[2], 0]));

    const ms = depth.sampleCount > 1;
    const bind = this.device.createBindGroup({
      layout: ms ? this.marchLayoutMS : this.marchLayout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: depth.createView() },
      ],
    });
    const pass = encoder.beginRenderPass({
      colorAttachments: [{ view: this.target.createView(), loadOp: 'clear', clearValue: { r: 0, g: 0, b: 0, a: 1 }, storeOp: 'store' }],
    });
    pass.setPipeline(ms ? this.marchPipelineMS : this.marchPipeline);
    pass.setBindGroup(0, bind);
    pass.draw(3);
    pass.end();
    this.rendered = true;
  }

  /** Add the shafts into the open scene pass (depth attached, write off). */
  composite(pass: GPURenderPassEncoder): void {
    if (!this.enabled || !this.rendered || !this.target) return;
    if (!this.compBind) {
      this.compBind = this.device.createBindGroup({
        layout: this.compLayout,
        entries: [
          { binding: 0, resource: this.sampler },
          { binding: 1, resource: this.target.createView() },
          { binding: 2, resource: { buffer: this.compUniforms } },
        ],
      });
    }
    pass.setPipeline(this.compPipeline);
    pass.setBindGroup(0, this.compBind);
    pass.draw(3);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.target = null;
    this.compBind = null;
    this.rendered = false;
    this.sampler = device.createSampler({ magFilter: 'linear', minFilter: 'linear' });
    this.uniforms = device.createBuffer({ size: UNIFORM_FLOATS * 4, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.compUniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });

    const layoutFor = (multisampled: boolean): GPUBindGroupLayout => device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: GPUShaderStage.FRAGMENT, texture: { sampleType: 'depth', multisampled } },
      ],
    });
    this.marchLayout = layoutFor(false);
    this.marchLayoutMS = layoutFor(true);
    const make = (ms: boolean, layout: GPUBindGroupLayout): GPURenderPipeline => {
      const module = shaderModule(device, raysWGSL(ms), ms ? 'rays-ms' : 'rays');
      return device.createRenderPipeline({
        layout: device.createPipelineLayout({ bindGroupLayouts: [layout] }),
        vertex: { module, entryPoint: 'vs' },
        fragment: { module, entryPoint: 'fs', targets: [{ format: 'r8unorm' }] },
        primitive: { topology: 'triangle-list' },
      });
    };
    this.marchPipeline = make(false, this.marchLayout);
    this.marchPipelineMS = make(true, this.marchLayoutMS);

    this.compLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: GPUShaderStage.FRAGMENT, sampler: {} },
        { binding: 1, visibility: GPUShaderStage.FRAGMENT, texture: {} },
        { binding: 2, visibility: GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
      ],
    });
    const cm = shaderModule(device, COMPOSITE_WGSL, 'rays-composite');
    this.compPipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.compLayout] }),
      vertex: { module: cm, entryPoint: 'vs' },
      fragment: {
        module: cm, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one' },
            alpha: { srcFactor: 'zero', dstFactor: 'one' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      primitive: { topology: 'triangle-list' },
    });
  }
}
