// LENS FLARE — the sun's signature on the camera (Rich Environments E4).
// A chain of procedural ghosts along the sun→screen-centre axis: the core
// glow + anamorphic streak + halo ring at the sun, then ghost discs walking
// through the centre and beyond (the classic internal-reflection chain).
// One instanced draw, additive, no textures.
//
// OCCLUSION is physical: the vertex shader reads the OPAQUE DEPTH in a
// 3×3 grid around the sun's pixel — a hill or building covering the sun
// collapses the whole chain smoothly. On by default whenever a sky is
// attached (sky.flare = false to opt out); the day/night dial colours and
// fades it via the same sun state as everything else.
import { BITS, shaderModule } from './gpu.js';
import { DEPTH_FORMAT } from './batch.js';

const N_ELEMS = 8;

function flareWGSL(ms: boolean): string {
  const depthDecl = ms ? 'var depthTex: texture_depth_multisampled_2d;' : 'var depthTex: texture_depth_2d;';
  return /* wgsl */ `
// Per element: (t along sun->centre axis, size px, type, alpha)
const EA = array<vec4f, ${N_ELEMS}>(
  vec4f(0.0, 150.0, 2.0, 0.42),   // anamorphic streak
  vec4f(0.0, 52.0, 0.0, 0.75),    // core glow
  vec4f(0.0, 105.0, 1.0, 0.2),    // halo ring
  vec4f(0.32, 20.0, 3.0, 0.28),   // ghost chain...
  vec4f(0.52, 10.0, 3.0, 0.24),
  vec4f(0.78, 30.0, 3.0, 0.18),
  vec4f(1.22, 46.0, 0.0, 0.14),   // ...through the centre
  vec4f(1.55, 16.0, 3.0, 0.2),
);
const EC = array<vec4f, ${N_ELEMS}>(
  vec4f(1.0, 0.95, 0.85, 0.0),
  vec4f(1.0, 0.97, 0.9, 0.0),
  vec4f(1.0, 0.85, 0.65, 0.0),
  vec4f(0.65, 1.0, 0.75, 0.0),
  vec4f(0.6, 0.85, 1.0, 0.0),
  vec4f(0.85, 0.65, 1.0, 0.0),
  vec4f(1.0, 0.8, 0.6, 0.0),
  vec4f(0.6, 1.0, 0.95, 0.0),
);

struct FU {
  sun: vec4f,   // sun ndc x, y, visibility, unused
  scr: vec4f,   // screenW, screenH, sunPxX, sunPxY
  color: vec4f, // sun rgb + unused
}
@group(0) @binding(0) var<uniform> fu: FU;
@group(0) @binding(1) ${depthDecl}

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uv: vec2f,
  @location(1) color: vec4f,
  @location(2) kind: f32,
}

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  var corners = array<vec2f, 6>(
    vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(-1.0, 1.0),
    vec2f(-1.0, 1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0),
  );
  let e = EA[ii];
  // OCCLUSION: how much of a 3x3 patch around the sun's pixel is SKY.
  var occ = 0.0;
  for (var oy = -1; oy <= 1; oy = oy + 1) {
    for (var ox = -1; ox <= 1; ox = ox + 1) {
      let px = vec2i(
        clamp(i32(fu.scr.z) + ox * 7, 0, i32(fu.scr.x) - 1),
        clamp(i32(fu.scr.w) + oy * 7, 0, i32(fu.scr.y) - 1),
      );
      occ += step(0.99995, textureLoad(depthTex, px, 0));
    }
  }
  occ /= 9.0;
  let vis = fu.sun.z * occ;
  let c = corners[vi];
  // Position: slide along the sun -> screen-centre axis by the element's t.
  let anchor = fu.sun.xy * (1.0 - e.x);
  var half = vec2f(e.y / fu.scr.x * 2.0, e.y / fu.scr.y * 2.0);
  if (e.z > 1.5 && e.z < 2.5) { half.x *= 6.0; half.y *= 0.55; }   // streak
  var out: VSOut;
  out.pos = vec4f(anchor + c * half * step(0.001, vis), 0.0, 1.0);
  out.uv = c;
  out.color = vec4f(EC[ii].rgb * fu.color.rgb, e.w * vis);
  out.kind = e.z;
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let r = length(in.uv);
  var a = 0.0;
  if (in.kind < 0.5) {                                   // soft glow disc
    a = pow(smoothstep(1.0, 0.0, r), 2.2);
  } else if (in.kind < 1.5) {                            // halo ring
    a = smoothstep(0.16, 0.0, abs(r - 0.7));
  } else if (in.kind < 2.5) {                            // anamorphic streak
    a = pow(max(1.0 - abs(in.uv.x), 0.0), 1.7) * pow(max(1.0 - abs(in.uv.y), 0.0), 2.5);
  } else {                                               // ghost disc
    a = smoothstep(1.0, 0.45, r) * (0.75 + 0.25 * smoothstep(0.0, 0.4, r));
  }
  let al = a * in.color.a;
  return vec4f(in.color.rgb * al, al);
}
`;
}

/** GPU plumbing — owned by World3d, drawn at the very end of pass B
 * (over the particles: flares are ON the lens). */
export class Flare3dLayer {
  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private buf!: GPUBuffer;
  private bind: GPUBindGroup | null = null;
  private depthView: GPUTextureView | null = null;
  private data = new Float32Array(12);
  visible = false;

  constructor(device: GPUDevice, private format: GPUTextureFormat, private sampleCount: number, private msDepth: boolean) {
    this.rebuild(device);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.bind = null;
    this.depthView = null;
    this.buf = device.createBuffer({ size: this.data.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST });
    const module = shaderModule(device, flareWGSL(this.msDepth), 'flare3d');
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: GPUShaderStage.VERTEX, texture: { sampleType: 'depth', multisampled: this.msDepth } },
      ],
    });
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one' },
            alpha: { srcFactor: 'zero', dstFactor: 'one' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      primitive: { topology: 'triangle-list' },
      multisample: { count: this.sampleCount },
    });
  }

  /** Per-frame uniforms. `vis` already carries night/storm/off-screen fade. */
  update(
    sunNdcX: number, sunNdcY: number, vis: number,
    color: [number, number, number],
    screenW: number, screenH: number, depthView: GPUTextureView,
  ): void {
    this.visible = vis > 0.002;
    if (!this.visible) return;
    if (depthView !== this.depthView || !this.bind) {
      this.depthView = depthView;
      this.bind = this.device.createBindGroup({
        layout: this.layout,
        entries: [
          { binding: 0, resource: { buffer: this.buf } },
          { binding: 1, resource: depthView },
        ],
      });
    }
    const px = (sunNdcX * 0.5 + 0.5) * screenW;
    const py = (0.5 - sunNdcY * 0.5) * screenH;
    const d = this.data;
    d.set([sunNdcX, sunNdcY, vis, 0], 0);
    d.set([screenW, screenH, px, py], 4);
    d.set([color[0], color[1], color[2], 0], 8);
    this.device.queue.writeBuffer(this.buf, 0, d);
  }

  draw(pass: GPURenderPassEncoder): void {
    if (!this.visible || !this.bind) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(6, N_ELEMS);
  }
}
