// NAV GRID — the ground-agent navigation tiers of the agents system (plan §6):
//
//   • Tier 1  A* over a heightfield grid: edge cost = horizontal distance ×
//             slope penalty; steep cells and cliff-height steps are cut, as are
//             cells below the water line or inside an obstacle. String-pulling
//             (line-of-sight smoothing) turns the staircase path into a few
//             waypoints. This is the forest monster that walks AROUND a
//             mountain and REFUSES a cliff.
//   • Tier 2  Flow field: one Dijkstra integration from a goal over the same
//             grid → a per-cell direction every agent samples in O(1). Beats
//             N × A* the moment a horde chases one target.
//
// Pure + GPU-free (built from `terrain.heightAt`), so it is dist-tested in
// Node. Tier 3 (recast navmesh over authored level geometry) is a later lazy
// chunk — not here.

export interface NavVec3 { x: number; y: number; z: number }

export interface NavGridOptions {
  /** Surface height at a world XZ (usually `terrain.heightAt`). */
  heightAt: (x: number, z: number) => number;
  /** World span of the (square) grid. */
  size: number;
  /** Grid centre in world XZ (default origin). */
  center?: { x: number; z: number };
  /** Cells per side (default 64). Coarser than the render mesh is fine. */
  res?: number;
  /** Steeper than this height-step BETWEEN adjacent cells is a cliff — cut. */
  maxStep?: number;
  /** Cost multiplier for climbing (0 = ignore slope, 3 = strongly prefer flat). */
  slopePenalty?: number;
  /** Cells whose surface is below this Y are unwalkable (water/void). */
  minY?: number;
  /** Extra per-cell mask — return false to block (obstacles, no-go zones). */
  blocked?: (x: number, z: number) => boolean;
}

const SQRT2 = Math.SQRT2;

export class NavGrid {
  readonly res: number;
  readonly cell: number;
  readonly ox: number;                 // world X of cell (0,0) centre
  readonly oz: number;
  readonly height: Float32Array;
  readonly walk: Uint8Array;
  private maxStep: number;
  private slopePenalty: number;

  constructor(o: NavGridOptions) {
    const res = this.res = Math.max(2, Math.floor(o.res ?? 64));
    const cx = o.center?.x ?? 0, cz = o.center?.z ?? 0;
    this.cell = o.size / res;
    this.ox = cx - o.size / 2 + this.cell / 2;
    this.oz = cz - o.size / 2 + this.cell / 2;
    this.maxStep = o.maxStep ?? this.cell * 1.2;
    this.slopePenalty = o.slopePenalty ?? 3;
    const n = res * res;
    this.height = new Float32Array(n);
    this.walk = new Uint8Array(n);
    for (let iz = 0; iz < res; iz++) {
      for (let ix = 0; ix < res; ix++) {
        const wx = this.ox + ix * this.cell, wz = this.oz + iz * this.cell;
        const h = o.heightAt(wx, wz);
        const i = iz * res + ix;
        this.height[i] = h;
        let ok = true;
        if (o.minY !== undefined && h < o.minY) ok = false;
        if (ok && o.blocked && o.blocked(wx, wz)) ok = false;
        this.walk[i] = ok ? 1 : 0;
      }
    }
  }

  idx(ix: number, iz: number): number { return iz * this.res + ix; }
  inBounds(ix: number, iz: number): boolean { return ix >= 0 && iz >= 0 && ix < this.res && iz < this.res; }
  cellCenter(ix: number, iz: number): NavVec3 {
    const i = this.idx(ix, iz);
    return { x: this.ox + ix * this.cell, y: this.height[i]!, z: this.oz + iz * this.cell };
  }
  worldToCell(x: number, z: number): { ix: number; iz: number } {
    return {
      ix: Math.min(this.res - 1, Math.max(0, Math.round((x - this.ox) / this.cell))),
      iz: Math.min(this.res - 1, Math.max(0, Math.round((z - this.oz) / this.cell))),
    };
  }
  walkableCell(ix: number, iz: number): boolean {
    return this.inBounds(ix, iz) && this.walk[this.idx(ix, iz)] === 1;
  }

  /** The nearest walkable cell to (ix,iz) by ring search (start/goal snap). */
  nearestWalkable(ix: number, iz: number): { ix: number; iz: number } | null {
    if (this.walkableCell(ix, iz)) return { ix, iz };
    for (let r = 1; r < this.res; r++) {
      for (let dz = -r; dz <= r; dz++) {
        for (let dx = -r; dx <= r; dx++) {
          if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;   // ring only
          if (this.walkableCell(ix + dx, iz + dz)) return { ix: ix + dx, iz: iz + dz };
        }
      }
    }
    return null;
  }

  /** True if the height STEP between adjacent walkable cells is passable. */
  private edgeOk(a: number, b: number): boolean {
    if (this.walk[a] !== 1 || this.walk[b] !== 1) return false;
    return Math.abs(this.height[a]! - this.height[b]!) <= this.maxStep;
  }

  /** A* over 8-connected cells. Returns a list of cell indices start→goal, or
   * null if unreachable (a cliff-ringed peak refuses a path). */
  astar(startX: number, startZ: number, goalX: number, goalZ: number): number[] | null {
    const s0 = this.worldToCell(startX, startZ), g0 = this.worldToCell(goalX, goalZ);
    const s = this.nearestWalkable(s0.ix, s0.iz), g = this.nearestWalkable(g0.ix, g0.iz);
    if (!s || !g) return null;
    const res = this.res, n = res * res;
    const start = this.idx(s.ix, s.iz), goal = this.idx(g.ix, g.iz);
    const gScore = new Float32Array(n).fill(Infinity);
    const fScore = new Float32Array(n).fill(Infinity);
    const came = new Int32Array(n).fill(-1);
    const open = new MinHeap(n);
    const inOpen = new Uint8Array(n);
    const cell = this.cell, slopeK = this.slopePenalty;
    const hx0 = goal % res, hz0 = (goal / res) | 0;
    const heur = (i: number): number => {
      const dx = Math.abs((i % res) - hx0), dz = Math.abs(((i / res) | 0) - hz0);
      const lo = Math.min(dx, dz), hi = Math.max(dx, dz);
      return (SQRT2 * lo + (hi - lo)) * cell;         // octile distance
    };
    gScore[start] = 0; fScore[start] = heur(start);
    open.push(start, fScore[start]!); inOpen[start] = 1;
    while (open.size > 0) {
      const cur = open.pop();
      inOpen[cur] = 0;
      if (cur === goal) return this.reconstruct(came, cur);
      const cx = cur % res, cz = (cur / res) | 0;
      for (let dz = -1; dz <= 1; dz++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dz === 0) continue;
          const nx = cx + dx, nz = cz + dz;
          if (nx < 0 || nz < 0 || nx >= res || nz >= res) continue;
          const nb = nz * res + nx;
          if (!this.edgeOk(cur, nb)) continue;
          if (dx !== 0 && dz !== 0) {                 // no diagonal cutting a blocked corner
            if (!this.edgeOk(cur, cz * res + nx) || !this.edgeOk(cur, nz * res + cx)) continue;
          }
          const dist = (dx !== 0 && dz !== 0 ? SQRT2 : 1) * cell;
          const rise = Math.abs(this.height[nb]! - this.height[cur]!);
          const step = gScore[cur]! + dist * (1 + slopeK * rise / cell);
          if (step < gScore[nb]!) {
            came[nb] = cur; gScore[nb] = step; fScore[nb] = step + heur(nb);
            if (!inOpen[nb]) { open.push(nb, fScore[nb]!); inOpen[nb] = 1; }
            else open.decrease(nb, fScore[nb]!);
          }
        }
      }
    }
    return null;
  }

  private reconstruct(came: Int32Array, cur: number): number[] {
    const out = [cur];
    while (came[cur] !== -1) { cur = came[cur]!; out.push(cur); }
    out.reverse();
    return out;
  }

  /** Walkable line-of-sight between two cells (supercover grid march). */
  lineOfSight(a: number, b: number): boolean {
    const res = this.res;
    let x0 = a % res, z0 = (a / res) | 0;
    const x1 = b % res, z1 = (b / res) | 0;
    const dx = Math.abs(x1 - x0), dz = Math.abs(z1 - z0);
    const sx = x0 < x1 ? 1 : -1, sz = z0 < z1 ? 1 : -1;
    let err = dx - dz;
    let prev = this.idx(x0, z0);
    for (;;) {
      const cur = this.idx(x0, z0);
      if (!this.edgeOk(prev, cur)) return false;
      prev = cur;
      if (x0 === x1 && z0 === z1) break;
      const e2 = 2 * err;
      if (e2 > -dz) { err -= dz; x0 += sx; }
      if (e2 < dx) { err += dx; z0 += sz; }
    }
    return true;
  }

  /** String-pull: drop interior cells the previous kept cell can see directly. */
  stringPull(cells: number[]): number[] {
    if (cells.length <= 2) return cells;
    const out = [cells[0]!];
    let anchor = 0;
    for (let i = 2; i < cells.length; i++) {
      if (!this.lineOfSight(cells[anchor]!, cells[i]!)) {
        out.push(cells[i - 1]!);
        anchor = i - 1;
      }
    }
    out.push(cells[cells.length - 1]!);
    return out;
  }

  /** Full plan start→goal as WORLD waypoints (cell centres at surface height).
   * Empty array when no path exists. */
  path(start: NavVec3, goal: NavVec3): NavVec3[] {
    const cells = this.astar(start.x, start.z, goal.x, goal.z);
    if (!cells) return [];
    const pulled = this.stringPull(cells);
    const res = this.res;
    return pulled.map((c) => this.cellCenter(c % res, (c / res) | 0));
  }

  /** Build a flow field: cost-to-goal by Dijkstra, then a per-cell direction
   * toward the cheapest neighbour. Every agent samples it O(1). */
  flowField(goal: NavVec3): FlowField {
    const res = this.res, n = res * res;
    const g0 = this.worldToCell(goal.x, goal.z);
    const g = this.nearestWalkable(g0.ix, g0.iz);
    const cost = new Float32Array(n).fill(Infinity);
    const dirx = new Float32Array(n);
    const dirz = new Float32Array(n);
    if (!g) return new FlowField(this, cost, dirx, dirz);
    const goalI = this.idx(g.ix, g.iz);
    const cell = this.cell, slopeK = this.slopePenalty;
    const open = new MinHeap(n);
    cost[goalI] = 0; open.push(goalI, 0);
    while (open.size > 0) {
      const cur = open.pop();
      const cx = cur % res, cz = (cur / res) | 0;
      for (let dz = -1; dz <= 1; dz++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dz === 0) continue;
          const nx = cx + dx, nz = cz + dz;
          if (nx < 0 || nz < 0 || nx >= res || nz >= res) continue;
          const nb = nz * res + nx;
          if (!this.edgeOk(cur, nb)) continue;
          if (dx !== 0 && dz !== 0 && (!this.edgeOk(cur, cz * res + nx) || !this.edgeOk(cur, nz * res + cx))) continue;
          const dist = (dx !== 0 && dz !== 0 ? SQRT2 : 1) * cell;
          const rise = Math.abs(this.height[nb]! - this.height[cur]!);
          const step = cost[cur]! + dist * (1 + slopeK * rise / cell);
          if (step < cost[nb]!) { cost[nb] = step; open.push(nb, step); }
        }
      }
    }
    // Direction = toward the walkable neighbour with the lowest cost.
    for (let iz = 0; iz < res; iz++) {
      for (let ix = 0; ix < res; ix++) {
        const i = iz * res + ix;
        if (this.walk[i] !== 1 || cost[i] === Infinity) continue;
        let best = cost[i]!, bx = 0, bz = 0;
        for (let dz = -1; dz <= 1; dz++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dz === 0) continue;
            const nx = ix + dx, nz = iz + dz;
            if (nx < 0 || nz < 0 || nx >= res || nz >= res) continue;
            const nb = nz * res + nx;
            if (!this.edgeOk(i, nb)) continue;
            if (cost[nb]! < best) { best = cost[nb]!; bx = dx; bz = dz; }
          }
        }
        const l = Math.hypot(bx, bz) || 1;
        dirx[i] = bx / l; dirz[i] = bz / l;
      }
    }
    return new FlowField(this, cost, dirx, dirz);
  }
}

/** A per-cell direction field toward a goal (Tier 2). */
export class FlowField {
  constructor(
    readonly grid: NavGrid,
    readonly cost: Float32Array,
    readonly dirx: Float32Array,
    readonly dirz: Float32Array,
  ) {}
  /** Steering direction at a world XZ (zero where unreachable/at goal). */
  dirAt(x: number, z: number): { x: number; z: number } {
    const { ix, iz } = this.grid.worldToCell(x, z);
    const i = this.grid.idx(ix, iz);
    return { x: this.dirx[i]!, z: this.dirz[i]! };
  }
  /** Whether a world XZ can reach the goal at all (finite cost). */
  reachable(x: number, z: number): boolean {
    const { ix, iz } = this.grid.worldToCell(x, z);
    return this.cost[this.grid.idx(ix, iz)]! < Infinity;
  }
}

// ── A tiny binary min-heap keyed by score (flat arrays, no allocation churn) ─

class MinHeap {
  private items: Int32Array;
  private prio: Float32Array;
  private pos: Int32Array;        // item → heap index (-1 = absent)
  size = 0;
  constructor(capacity: number) {
    this.items = new Int32Array(capacity);
    this.prio = new Float32Array(capacity);
    this.pos = new Int32Array(capacity).fill(-1);
  }
  push(item: number, p: number): void {
    let i = this.size++;
    this.items[i] = item; this.prio[i] = p; this.pos[item] = i;
    this.up(i);
  }
  decrease(item: number, p: number): void {
    const i = this.pos[item]!;
    if (i < 0 || p >= this.prio[i]!) return;
    this.prio[i] = p; this.up(i);
  }
  pop(): number {
    const top = this.items[0]!;
    this.pos[top] = -1;
    const last = --this.size;
    if (last > 0) {
      this.items[0] = this.items[last]!; this.prio[0] = this.prio[last]!;
      this.pos[this.items[0]!] = 0; this.down(0);
    }
    return top;
  }
  private up(i: number): void {
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.prio[i]! >= this.prio[parent]!) break;
      this.swap(i, parent); i = parent;
    }
  }
  private down(i: number): void {
    for (;;) {
      const l = i * 2 + 1, r = l + 1;
      let m = i;
      if (l < this.size && this.prio[l]! < this.prio[m]!) m = l;
      if (r < this.size && this.prio[r]! < this.prio[m]!) m = r;
      if (m === i) break;
      this.swap(i, m); i = m;
    }
  }
  private swap(a: number, b: number): void {
    const it = this.items[a]!; this.items[a] = this.items[b]!; this.items[b] = it;
    const pr = this.prio[a]!; this.prio[a] = this.prio[b]!; this.prio[b] = pr;
    this.pos[this.items[a]!] = a; this.pos[this.items[b]!] = b;
  }
}
