// VOLUMETRIC SPOTLIGHT BEAMS — the visible "cone of light" a flashlight,
// searchlight or lighthouse throws through haze. Each beam is a cone generated
// in the VERTEX shader from a handful of per-instance floats (apex, axis,
// length, base radius, colour, intensity) — no mesh, one instanced draw for
// every beam in the world.
//
// Two things a plain translucent cone cannot do, and the reason this is its
// own layer, both live in the fragment stage:
//   1. It SHADES LIKE LIGHT: additive, brightest down the core and soft at the
//      silhouette (a fresnel-ish |N·V| term — the near and far walls both add,
//      so the middle glows), fading along its length from the lamp.
//   2. It DOESN'T CUT THROUGH THE WORLD: it samples the opaque depth (the same
//      read-only depth the water shore-blend and soft particles use) and fades
//      out as it approaches a solid, so the shaft dissolves into a hillside
//      instead of slicing through it.
//
// Drawn in pass B (translucent, depth-tested read-only) so solids in front
// still occlude it. Owned by World3d; fed by world.light({ beam }).
import { BITS, shaderModule } from './gpu.js';
import { DEPTH_FORMAT } from './batch.js';

const SEGS = 40;                 // cone facets — one triangle (apex, ring, ring) each
const VERTS = SEGS * 3;
const U_FLOATS = 24;             // viewProj mat4 (16) + camPos vec4 (4) + lin vec4 (4)
const INST_FLOATS = 12;          // apex vec4 + axis vec4 + color vec4

function beamWGSL(ms: boolean): string {
  const depthDecl = ms ? 'var depthTex: texture_depth_multisampled_2d;' : 'var depthTex: texture_depth_2d;';
  return /* wgsl */ `
const SEGS = ${SEGS}u;
const TAU = 6.2831853;

struct U {
  viewProj: mat4x4f,
  camPos: vec4f,
  lin: vec4f,          // projA, projB, softDist, unused  (viewDist = projB/(projA+depth))
}
struct Inst {
  apex: vec4f,         // x, y, z, length
  axis: vec4f,         // dir xyz (normalised on CPU), base radius
  color: vec4f,        // rgb, intensity (additive core strength)
}
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@group(0) @binding(2) ${depthDecl}

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) world: vec3f,
  @location(1) nrm: vec3f,
  @location(2) axial: f32,        // 0 at the lamp (apex) → 1 at the base
  @location(3) viewDist: f32,     // linear eye distance of this fragment
  @location(4) color: vec4f,      // rgb + intensity
}

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let b = inst[ii];
  let seg = vi / 3u;
  let corner = vi % 3u;
  let apex = b.apex.xyz;
  let L = b.apex.w;
  let axis = normalize(b.axis.xyz);
  let R = b.axis.w;
  // An orthonormal basis across the axis (guard the near-parallel up vector).
  var up = vec3f(0.0, 1.0, 0.0);
  if (abs(axis.y) > 0.99) { up = vec3f(1.0, 0.0, 0.0); }
  let uu = normalize(cross(up, axis));
  let vv = cross(axis, uu);
  let baseC = apex + axis * L;
  let a0 = f32(seg) / f32(SEGS) * TAU;
  let a1 = f32(seg + 1u) / f32(SEGS) * TAU;

  var world: vec3f;
  var axial: f32;
  var nrm: vec3f;
  if (corner == 0u) {
    world = apex;
    axial = 0.0;
    let am = (a0 + a1) * 0.5;                       // mid radial for the apex vertex
    nrm = cos(am) * uu + sin(am) * vv;
  } else {
    let ang = select(a0, a1, corner == 2u);
    let radial = cos(ang) * uu + sin(ang) * vv;
    world = baseC + radial * R;
    axial = 1.0;
    // Cone side normal: radial tilted toward the apex by the slope R/L.
    nrm = normalize(radial * L - axis * R);
  }
  var out: VSOut;
  out.pos = u.viewProj * vec4f(world, 1.0);
  out.world = world;
  out.nrm = nrm;
  out.axial = axial;
  out.viewDist = out.pos.w;                          // clip w = linear eye distance
  out.color = b.color;
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let V = normalize(u.camPos.xyz - in.world);
  let N = normalize(in.nrm);
  // Bright down the CORE, soft at the silhouette: |N·V| ~1 where a wall faces
  // the eye (the middle of the cone, near + far walls both adding), ~0 grazing.
  let face = abs(dot(N, V));
  var a = in.color.a * face * face;
  // Fade along the shaft (brightest at the lamp) and soften the exact apex.
  a *= mix(1.0, 0.16, in.axial);
  a *= smoothstep(0.0, 0.06, in.axial);
  // SOFT DEPTH FADE — dissolve as the shaft nears a solid (no cut-through).
  let d = textureLoad(depthTex, vec2i(in.pos.xy), 0);
  if (d < 1.0) {
    let sceneDist = u.lin.y / (u.lin.x + d);
    a *= clamp((sceneDist - in.viewDist) / max(u.lin.z, 0.001), 0.0, 1.0);
  }
  // Premultiplied additive: alpha channel 0 keeps the blend purely additive.
  return vec4f(in.color.rgb * a, 0.0);
}
`;
}

/** GPU plumbing for the spotlight beams — owned by World3d, drawn in pass B. */
export class Beam3dLayer {
  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private ubuf!: GPUBuffer;
  private ibuf!: GPUBuffer;
  private bind: GPUBindGroup | null = null;
  private depthView: GPUTextureView | null = null;
  private udata = new Float32Array(U_FLOATS);
  private idata = new Float32Array(64 * INST_FLOATS);
  private count = 0;

  constructor(device: GPUDevice, private format: GPUTextureFormat, private sampleCount: number, private msDepth: boolean) {
    this.rebuild(device);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.bind = null;
    this.depthView = null;
    this.ubuf = device.createBuffer({ size: U_FLOATS * 4, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.ibuf = device.createBuffer({ size: this.idata.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
    const module = shaderModule(device, beamWGSL(this.msDepth), 'beam3d');
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: GPUShaderStage.VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: GPUShaderStage.FRAGMENT, texture: { sampleType: 'depth', multisampled: this.msDepth } },
      ],
    });
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one' },   // additive
            alpha: { srcFactor: 'zero', dstFactor: 'one' },
          },
        }],
      },
      // Depth-TESTED (occluded by nearer solids) but never written; both cone
      // walls rasterise (cull none) so the volume reads from every angle.
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-list', cullMode: 'none' },
      multisample: { count: this.sampleCount },
    });
  }

  /**
   * Pack one instance per live beam and refresh the uniform. `beams` are the
   * light + its beam config; the geometry follows the light's pose/dir/cone
   * every frame. projA/projB linearise the sampled depth (see World3d.projInfo).
   */
  update(
    beams: ReadonlyArray<{ light: BeamLight; opts: BeamOpts }>,
    viewProj: ArrayLike<number>, camX: number, camY: number, camZ: number,
    projA: number, projB: number, softDist: number,
    depthView: GPUTextureView,
  ): void {
    this.count = 0;
    if (!beams.length) return;
    if (beams.length * INST_FLOATS > this.idata.length) {
      let len = this.idata.length;
      while (len < beams.length * INST_FLOATS) len *= 2;
      this.idata = new Float32Array(len);
      this.ibuf.destroy();
      this.ibuf = this.device.createBuffer({ size: this.idata.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
      this.bind = null;
    }
    for (const b of beams) {
      const l = b.light;
      const len = b.opts.length ?? l.radius;
      const dl = Math.hypot(l.dir.x, l.dir.y, l.dir.z) || 1;
      const R = len * Math.tan(Math.min(1.45, Math.max(0.01, l.cone.outer)));
      const c = b.opts.rgb;
      const o = this.count * INST_FLOATS;
      const d = this.idata;
      d[o] = l.x; d[o + 1] = l.y; d[o + 2] = l.z; d[o + 3] = len;
      d[o + 4] = l.dir.x / dl; d[o + 5] = l.dir.y / dl; d[o + 6] = l.dir.z / dl; d[o + 7] = R;
      d[o + 8] = c[0]; d[o + 9] = c[1]; d[o + 10] = c[2]; d[o + 11] = b.opts.intensity ?? 0.6;
      this.count++;
    }
    const u = this.udata;
    u.set(viewProj, 0);
    u[16] = camX; u[17] = camY; u[18] = camZ; u[19] = 0;
    u[20] = projA; u[21] = projB; u[22] = softDist; u[23] = 0;
    this.device.queue.writeBuffer(this.ubuf, 0, u);
    this.device.queue.writeBuffer(this.ibuf, 0, this.idata.buffer, 0, this.count * INST_FLOATS * 4);
    if (depthView !== this.depthView || !this.bind) {
      this.depthView = depthView;
      this.bind = this.device.createBindGroup({
        layout: this.layout,
        entries: [
          { binding: 0, resource: { buffer: this.ubuf } },
          { binding: 1, resource: { buffer: this.ibuf } },
          { binding: 2, resource: depthView },
        ],
      });
    }
  }

  draw(pass: GPURenderPassEncoder): void {
    if (!this.count || !this.bind) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(VERTS, this.count);
  }
}

/** The subset of a Light3d the beam reads (structural — avoids an import cycle). */
interface BeamLight {
  x: number; y: number; z: number;
  radius: number;
  dir: { x: number; y: number; z: number };
  cone: { inner: number; outer: number };
}
interface BeamOpts {
  length?: number;
  intensity?: number;
  /** Pre-resolved rgb (0..1) — World3d resolves the colour string once. */
  rgb: [number, number, number];
}
